            return0; 
        if(dp[n, W] != -1) 
            returndp[n, W]; 
        if(wt[n - 1] > W) 
 
            // Store the value of function call 
            // stack in table before return 
            returndp[n, W] 
                = knapSackRec(W, wt, val, n - 1, dp); 
 
        else
 
            // Return value of table after storing 
            returndp[n, W] 
                = max((val[n - 1] 
                       + knapSackRec(W - wt[n - 1], wt, val, 
