// Here is the top-down approach of 
// dynamic programming 
#include <bits/stdc++.h> 
usingnamespacestd; 
 
// Returns the value of maximum profit 
intknapSackRec(intW, intwt[], intval[], intindex, int** dp) 
{ 
    // base condition 
    if(index < 0) 
        return0; 
    if(dp[index][W] != -1) 
        returndp[index][W]; 
 
    if(wt[index] > W) { 
 
        // Store the value of function call 
        // stack in table before return 
        dp[index][W] = knapSackRec(W, wt, val, index - 1, dp); 
        returndp[index][W]; 
    } 
    else{ 
        // Store value in a table before return 
        dp[index][W] = max(val[index] 
                           + knapSackRec(W - wt[index], wt, val, 
                                         index - 1, dp), 
                       knapSackRec(W, wt, val, index - 1, dp)); 
 
        // Return value of table after storing 
        returndp[index][W]; 
    } 
} 
 
intknapSack(intW, intwt[], intval[], intn) 
{ 
    // double pointer to declare the 
    // table dynamically 
    int** dp; 
    dp = newint*[n]; 
 
    // loop to create the table dynamically 
    for(inti = 0; i < n; i++) 
        dp[i] = newint[W + 1]; 
 
    // loop to initially filled the 
    // table with -1 
    for(inti = 0; i < n; i++) 
        for(intj = 0; j < W + 1; j++) 
            dp[i][j] = -1; 
    returnknapSackRec(W, wt, val, n - 1, dp); 
} 
 
// Driver Code 
intmain() 
{ 
    intprofit[] = { 60, 100, 120 }; 
    intweight[] = { 10, 20, 30 }; 
    intW = 50; 
    intn = sizeof(profit) / sizeof(profit[0]); 
    cout << knapSack(W, weight, profit, n); 
    return0; 
