usingSystem; 
usingSystem.Collections.Generic; 
usingSystem.Linq; 
 
classItem { 
    publicintvalue; 
    publicintweight; 
    publicdoubleratio; 
 
    publicItem(intvalue, intweight) 
    { 
        this.value = value; 
        this.weight = weight; 
        this.ratio = (double)value / weight; 
    } 
} 
 
classKnapsackNode { 
    publicList<int> items; 
    publicintvalue; 
    publicintweight; 
    publicKnapsackNode(List<int> items, intvalue, 
                        intweight) 
    { 
        this.items = items; 
        this.value = value; 
        this.weight = weight; 
    } 
} 
 
classKnapsack { 
    publicintmaxWeight; 
    publicList<Item> items; 
    publicKnapsack(intmaxWeight, List<Item> items) 
    { 
        this.maxWeight = maxWeight; 
        this.items = items; 
    } 
 
    publicintSolve() 
    { 
        items = items.OrderByDescending(i = > i.ratio) 
                    .ToList(); 
 
        intbestValue = 0; 
        Queue<KnapsackNode> q = newQueue<KnapsackNode>(); 
        q.Enqueue(newKnapsackNode(newList<int>(), 0, 0)); 
 
        while(q.Count > 0) { 
            KnapsackNode node = q.Dequeue(); 
            inti = node.items.Count; 
 
            if(i == items.Count) { 
                bestValue = Math.Max(bestValue, node.value); 
            } 
            else{ 
                Item item = items[i]; 
                KnapsackNode withItem = newKnapsackNode( 
                    newList<int>(node.items), 
                    node.value + item.value, 
                    node.weight + item.weight); 
                if(IsPromising(withItem, maxWeight, 
                                bestValue)) { 
                    q.Enqueue(withItem); 
                } 
                KnapsackNode withoutItem = newKnapsackNode( 
