// Java Program to print path from root node to destination node
// for N*N -1 puzzle algorithm using Branch and Bound
// The solution assumes that instance of puzzle is solvable
importjava.io.*;
importjava.util.*;

classGFG
{    
    publicstaticintN = 3;
    publicstaticclassNode
    {
      
        // stores the parent node of the current node
        // helps in tracing path when the answer is found
        Node parent;
        intmat[][] = newint[N][N];// stores matrix
        intx, y;// stores blank tile coordinates
        intcost;// stores the number of misplaced tiles
        intlevel;// stores the number of moves so far
    }
    
    // Function to print N x N matrix
    publicstaticvoidprintMatrix(intmat[][]){
        for(inti = 0; i < N; i++){
            for(intj = 0; j < N; j++){
                System.out.print(mat[i][j]+" ");
            }
            System.out.println("");
        }
    }
    
    // Function to allocate a new node
    publicstaticNode newNode(intmat[][], intx, inty, 
                               intnewX, intnewY, intlevel, 
                               Node parent){
        Node node = newNode();
        node.parent = parent;// set pointer for path to root
        
        // copy data from parent node to current node
        node.mat = newint[N][N];
        for(inti = 0; i < N; i++){
            for(intj = 0; j < N; j++){
                node.mat[i][j] = mat[i][j];
            }
        }
        
        // move tile by 1 position
        inttemp = node.mat[x][y];
        node.mat[x][y] = node.mat[newX][newY];
        node.mat[newX][newY]=temp;
        
        node.cost = Integer.MAX_VALUE;// set number of misplaced tiles
        node.level = level;// set number of moves so far
        
        // update new blank tile coordinates
        node.x = newX;
        node.y = newY;
        
        returnnode;
    }
    
    // bottom, left, top, right
    publicstaticintrow[] = { 1, 0, -1, 0};
    publicstaticintcol[] = { 0, -1, 0, 1};
    
    // Function to calculate the number of misplaced tiles
    // ie. number of non-blank tiles not in their goal position
    publicstaticintcalculateCost(intinitialMat[][], intfinalMat[][])
    {
        intcount = 0;
        for(inti = 0; i < N; i++)
          for(intj = 0; j < N; j++)
            if(initialMat[i][j]!=0&& initialMat[i][j] != finalMat[i][j])
               count++;
        returncount;
    }
     
    // Function to check if (x, y) is a valid matrix coordinate
    publicstaticintisSafe(intx, inty)
    {
        return(x >= 0&& x < N && y >= 0&& y < N)?1:0;
    }
    
    // print path from root node to destination node
    publicstaticvoidprintPath(Node root){
        if(root == null){
            return;
        }
        printPath(root.parent);
        printMatrix(root.mat);
        System.out.println("");
    }
    
    // Comparison object to be used to order the heap
    publicstaticclasscomp implementsComparator<Node>{
        @Override
        publicintcompare(Node lhs, Node rhs){
            return(lhs.cost + lhs.level) > (rhs.cost+rhs.level)?1:-1;
        }
    } 
    
    // Function to solve N*N - 1 puzzle algorithm using
    // Branch and Bound. x and y are blank tile coordinates
    // in initial state
    publicstaticvoidsolve(intinitialMat[][], intx, 
                             inty, intfinalMat[][])
    {
      
        // Create a priority queue to store live nodes of search tree
        PriorityQueue<Node> pq = newPriorityQueue<>(newcomp());
        
        // create a root node and calculate its cost
        Node root = newNode(initialMat, x, y, x, y, 0, null);
        root.cost = calculateCost(initialMat,finalMat);
        
        // Add root to list of live nodes;
        pq.add(root);
        
        // Finds a live node with least cost,
        // add its childrens to list of live nodes and
        // finally deletes it from the list.
        while(!pq.isEmpty())
        {
            Node min = pq.peek();// Find a live node with least estimated cost
            pq.poll();// The found node is deleted from the list of live nodes
            
            // if min is an answer node
            if(min.cost == 0){
                printPath(min);// print the path from root to destination;
                return;
            }
            // do for each child of min
            // max 4 children for a node
            for(inti = 0; i < 4; i++)
            {
                if(isSafe(min.x + row[i], min.y + col[i])>0)
                {
                    // create a child node and calculate
                    // its cost
                    Node child = newNode(min.mat, min.x, min.y, min.x + row[i],min.y + col[i], min.level + 1, min);
                    child.cost = calculateCost(child.mat, finalMat);
     
                    // Add child to list of live nodes
                    pq.add(child);
                }
            }
        }
    }
    
    //Driver Code
    publicstaticvoidmain (String[] args)
    {
      
        // Initial configuration
        // Value 0 is used for empty space
        intinitialMat[][] =
        {
            {1, 2, 3},
            {5, 6, 0},
            {7, 8, 4}
        };
     
        // Solvable Final configuration
        // Value 0 is used for empty space
        intfinalMat[][] =
        {
            {1, 2, 3},
            {5, 8, 6},
            {0, 7, 4}
        };
     
        // Blank tile coordinates in initial
        // configuration
        intx = 1, y = 2;
     
        solve(initialMat, x, y, finalMat);
    }
}

