    // entire row and column to 0.
    staticvoidSetZeroes(List<List<int> > matrix)
    {
        introws = matrix.Count, cols = matrix[0].Count;

        // Iterate through each element of the matrix
        for(inti = 0; i < rows; i++) {
            for(intj = 0; j < cols; j++) {

                // If the element is 1, mark its
                // corresponding row and column using -1
                if(matrix[i][j] == 1) {

                    // Mark all elements in the same column
                    // as -1, except for other 1's
                    intind = i - 1;
                    while(ind >= 0) {
                        if(matrix[ind][j] != 1) {
                            matrix[ind][j] = -1;
                        }
                        ind--;
                    }
                    ind = i + 1;
                    while(ind < rows) {
                        if(matrix[ind][j] != 1) {
                            matrix[ind][j] = -1;
                        }
                        ind++;
                    }

                    // Mark all elements in the same row as
                    // -1, except for other 1's
                    ind = j - 1;
                    while(ind >= 0) {
                        if(matrix[i][ind] != 1) {
                            matrix[i][ind] = -1;
                        }
                        ind--;
                    }
                    ind = j + 1;
                    while(ind < cols) {
                        if(matrix[i][ind] != 1) {
                            matrix[i][ind] = -1;
                        }
                        ind++;
                    }
                }
            }
        }

        // Iterate through the matrix again, setting all
        // -1's to 0
        for(inti = 0; i < rows; i++) {
            for(intj = 0; j < cols; j++) {
                if(matrix[i][j] < 0) {
                    matrix[i][j] = 1;
                }
