                    // Mark all elements in the same row as
                    // -1, except for other 1's
                    ind = j - 1;
                    while(ind >= 0) {
                        if(matrix[i][ind] != 1) {
                            matrix[i][ind] = -1;
                        }
                        ind--;
                    }
                    ind = j + 1;
                    while(ind < cols) {
                        if(matrix[i][ind] != 1) {
                            matrix[i][ind] = -1;
                        }
                        ind++;
                    }
                }
            }
        }

        // Iterate through the matrix again, setting all
        // -1's to 0
        for(inti = 0; i < rows; i++) {
            for(intj = 0; j < cols; j++) {
                if(matrix[i][j] < 0) {
                    matrix[i][j] = 1;
                }
            }
        }
