// C++ program of AVL tree that
// handles duplicates
#include <stdio.h>
#include <stdlib.h>

// An AVL tree node
structnode {
    intkey;
    structnode* left;
    structnode* right;
    intheight;
    intcount;
};

// A utility function to get maximum of two integers
intmax(inta, intb);

// A utility function to get height of the tree
intheight(structnode* N)
{
    if(N == NULL)
        return0;
    returnN->height;
}

// A utility function to get maximum of two integers
intmax(inta, intb)
{
    return(a > b) ? a : b;
}

/* Helper function that allocates a new node with the given key and
    NULL left and right pointers. */
structnode* newNode(intkey)
{
    structnode* node = (structnode*)
        malloc(sizeof(structnode));
    node->key = key;
    node->left = NULL;
    node->right = NULL;
    node->height = 1; // new node is initially added at leaf
    node->count = 1;
    return(node);
}

// A utility function to right rotate subtree rooted with y
// See the diagram given above.
structnode* rightRotate(structnode* y)
{
    structnode* x = y->left;
    structnode* T2 = x->right;

    // Perform rotation
    x->right = y;
    y->left = T2;

    // Update heights
    y->height = max(height(y->left), height(y->right)) + 1;
    x->height = max(height(x->left), height(x->right)) + 1;

    // Return new root
    returnx;
}

// A utility function to left rotate subtree rooted with x
// See the diagram given above.
structnode* leftRotate(structnode* x)
{
    structnode* y = x->right;
    structnode* T2 = y->left;

    // Perform rotation
    y->left = x;
    x->right = T2;

    // Update heights
    x->height = max(height(x->left), height(x->right)) + 1;
    y->height = max(height(y->left), height(y->right)) + 1;

    // Return new root
    returny;
}

// Get Balance factor of node N
intgetBalance(structnode* N)
{
    if(N == NULL)
        return0;
    returnheight(N->left) - height(N->right);
}

structnode* insert(structnode* node, intkey)
{
    /* 1.  Perform the normal BST rotation */
    if(node == NULL)
