// Constructor 
publicMinHeap(intn)
{
    capacity = n;
    heapArray = newint[capacity];
    current_heap_size = 0;
}

// Swapping using reference 
publicstaticvoidSwap<T>(refT lhs, refT rhs)
{
    T temp = lhs;
    lhs = rhs;
    rhs = temp;
}

// Get the Parent index for the given index
publicintParent(intkey) 
{
    return(key - 1) / 2;
}

// Get the Left Child index for the given index
publicintLeft(intkey)
{
    return2 * key + 1;
}

// Get the Right Child index for the given index
publicintRight(intkey)
{
    return2 * key + 2;
}

// Inserts a new key
publicboolinsertKey(intkey)
{
    if(current_heap_size == capacity)
    {
        
        // heap is full
        returnfalse;
    }

    // First insert the new key at the end 
    inti = current_heap_size;
    heapArray[i] = key;
    current_heap_size++;

    // Fix the min heap property if it is violated 
    while(i != 0 && heapArray[i] < 
                     heapArray[Parent(i)])
    {
        Swap(refheapArray[i],
             refheapArray[Parent(i)]);
        i = Parent(i);
    }
    returntrue;
}

// Decreases value of given key to new_val. 
// It is assumed that new_val is smaller 
// than heapArray[key]. 
publicvoiddecreaseKey(intkey, intnew_val)
{
    heapArray[key] = new_val;

    while(key != 0 && heapArray[key] < 
                       heapArray[Parent(key)])
    {
        Swap(refheapArray[key], 
             refheapArray[Parent(key)]);
        key = Parent(key);
    }
}

// Returns the minimum key (key at
// root) from min heap 
publicintgetMin()
{
    returnheapArray[0];
}

// Method to remove minimum element 
// (or root) from min heap 
publicintextractMin()
{
    if(current_heap_size <= 0)
    {
        returnint.MaxValue;
    }

    if(current_heap_size == 1)
    {
        current_heap_size--;
        returnheapArray[0];
    }

    // Store the minimum value, 
    // and remove it from heap 
    introot = heapArray[0];

    heapArray[0] = heapArray[current_heap_size - 1];
    current_heap_size--;
    MinHeapify(0);

    returnroot;
}

// This function deletes key at the 
// given index. It first reduced value 
// to minus infinite, then calls extractMin()
publicvoiddeleteKey(intkey)
{
    decreaseKey(key, int.MinValue);
    extractMin();
}

// A recursive method to heapify a subtree 
// with the root at given index 
// This method assumes that the subtrees
// are already heapified
publicvoidMinHeapify(intkey)
{
    intl = Left(key);
    intr = Right(key);

    intsmallest = key;
    if(l < current_heap_size && 
        heapArray[l] < heapArray[smallest])
    {
        smallest = l;
    }
    if(r < current_heap_size && 
        heapArray[r] < heapArray[smallest])
    {
        smallest = r;
    }
    
    if(smallest != key)
    {
        Swap(refheapArray[key], 
             refheapArray[smallest]);
        MinHeapify(smallest);
    }
}

// Increases value of given key to new_val.
// It is assumed that new_val is greater 
// than heapArray[key]. 
// Heapify from the given key
publicvoidincreaseKey(intkey, intnew_val)
{
    heapArray[key] = new_val;
    MinHeapify(key);
}

// Changes value on a key
publicvoidchangeValueOnAKey(intkey, intnew_val)
{
    if(heapArray[key] == new_val)
    {
        return;
    }
    if(heapArray[key] < new_val)
    {
        increaseKey(key, new_val);
