functionconstructBST(nodes, start, end) {
    if(start > end) {
        returnnull;
    }
    const mid = Math.floor((start + end) / 2);
    const root = nodes[mid];
    root.left = constructBST(nodes, start, mid - 1);
    root.right = constructBST(nodes, mid + 1, end);
    returnroot;
}

// Function to convert a binary tree to a binary search tree
functionconvertToBST(root) {
    const nodes = [];
    inorder(root, nodes);
    nodes.sort((a, b) => a.val - b.val);
    returnconstructBST(nodes, 0, nodes.length - 1);
}

