     * array size*/
    if(d > n) 
        d = d % n; 
    i = d; 
    j = n - d; 
    while(i != j) { 
        if(i < j) /*A is shorter*/
        { 
            swap(arr, d - i, d + j - i, i); 
            j -= i; 
        } 
        else/*B is shorter*/
        { 
            swap(arr, d - i, d, j); 
            i -= j; 
        } 
