                check = stack.pop();
                if(check == '('|| check == '[')
                    returnfalse;
                break;

            case']':
                check = stack.pop();
                if(check == '('|| check == '{')
                    returnfalse;
                break;
            }
        }

        // Check Empty Stack
        return(stack.isEmpty());
    }

