// square, otherwise false
staticboolisSquare(Point p1, Point p2, Point p3, Point p4)
{
    intd2 = distSq(p1, p2); // from p1 to p2
    intd3 = distSq(p1, p3); // from p1 to p3
    intd4 = distSq(p1, p4); // from p1 to p4

    if(d2 == 0 || d3 == 0 || d4 == 0)    
        returnfalse;

    // If lengths if (p1, p2) and (p1, p3) are same, then
    // following conditions must met to form a square.
