                r--;
        }
        returnfalse;
    }

    /* Below functions are only to sort the
    array using QuickSort */

    /* This function takes last element as pivot,
    places the pivot element at its correct
    position in sorted array, and places all
    smaller (smaller than pivot) to left of
    pivot and all greater elements to right
    of pivot */
    staticintpartition(int[] arr, intlow, inthigh)
    {
        intpivot = arr[high];

        // index of smaller element
        inti = (low - 1);
        for(intj = low; j <= high - 1; j++) {
            // If current element is smaller
            // than or equal to pivot
            if(arr[j] <= pivot) {
                i++;

                // swap arr[i] and arr[j]
                inttemp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }

        // swap arr[i+1] and arr[high] (or pivot)
        inttemp1 = arr[i + 1];
        arr[i + 1] = arr[high];
        arr[high] = temp1;

        returni + 1;
    }

    /* The main function that
    implements QuickSort()
    arr[] --> Array to be sorted,
    low --> Starting index,
    high --> Ending index */
    staticvoidsort(int[] arr, intlow, inthigh)
    {
        if(low < high) {
            /* pi is partitioning index, arr[pi]
            is now at right place */
            intpi = partition(arr, low, high);

            // Recursively sort elements before
            // partition and after partition
            sort(arr, low, pi - 1);
            sort(arr, pi + 1, high);
        }
    }

