    publicstaticTree cloneTree(Tree tree)
    {
        if(tree == null)
            returnnull;
        HashMap<Tree, Tree> map
            = newHashMap<>(); // create a hashmap to store
                               // the randoms
        Tree newtree = clonelr(tree, map);
