        {
            if(Math.Abs(p.x - midPoint.x) < d)
            {
                strip.Add(p);
            }
        }
        returnStripClosest(strip.ToArray(), strip.Count, d);
    }
    
    // A Brute Force method to return the smallest distance between two points
    // in P[] of size n
