class Point {
  constructor(x, y) {
    this.x = x;
    this.y = y;
  }
}

// Needed to sort array of points according to X coordinate
functioncompareX(a, b) {
  let p1 = a,
    p2 = b;
  return(p1.x !== p2.x) * (p1.x - p2.x) + (p1.y - p2.y);
}

// Needed to sort array of points according to Y coordinate
functioncompareY(a, b) {
  let p1 = a,
    p2 = b;
  return(p1.y !== p2.y) * (p1.y - p2.y) + (p1.x - p2.x);
}

// A utility function to find the distance between two points
functiondist(p1, p2) {
  returnMath.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
}

// A Brute Force method to return the smallest distance between two points
// in P[] of size n
functionbruteForce(P, n) {
  let min = Number.POSITIVE_INFINITY;
  for(let i = 0; i < n; i++) {
    for(let j = i + 1; j < n; j++) {
      if(dist(P[i], P[j]) < min) {
        min = dist(P[i], P[j]);
      }
    }
  }
  returnmin;
}

// A utility function to find a minimum of two float values
functionmin(x, y) {
  returnx < y ? x : y;
}

// A utility function to find the distance between the closest points of
// strip of a given size. All points in strip[] are sorted according to
// y coordinate. They all have an upper bound on minimum distance as d.
// Note that this method seems to be a O(n^2) method, but it's a O(n)
// method as the inner loop runs at most 6 times
functionstripClosest(strip, size, d) {
  let min = d; // Initialize the minimum distance as d

  // Pick all points one by one and try the next points till the difference
  // between y coordinates is smaller than d.
  // This is a proven fact that this loop runs at most 6 times
  for(let i = 0; i < size; i++) {
    for(let j = i + 1; j < size; j++) {
      if(strip[j].y - strip[i].y < min) {
        if(dist(strip[i], strip[j]) < min) {
          min = dist(strip[i], strip[j]);
        }
      }
    }
  }

  returnmin;
}

// A recursive function to find the smallest distance. The array Px contains
// all points sorted according to x coordinates and Py contains all points
// sorted according to y coordinates
functionclosestUtil(Px, Py, n) {
  // If there are 2 or 3 points, then use brute force
  if(n <= 3) {
    returnbruteForce(Px, n);
  }

  // Find the middle point
  let mid = Math.floor(n / 2);
  let midPoint = Px[mid];

  // Divide points in y sorted array around the vertical line.
  // Assumption: All x coordinates are distinct.
  let Pyl = newArray(mid); // y sorted points on left of vertical line
  let Pyr = newArray(n - mid); // y sorted points on right of vertical line
  let li = 0;
  let ri = 0; // indexes of left and right subarrays
  for(let i = 0; i < n; i++) {
    if(
      (Py[i].x < midPoint.x || (Py[i].x === midPoint.x && Py[i].y < midPoint.y)) &&
      li < mid
    ) {
      Pyl[li] = Py[i];
      li++;
    } else{
      Pyr[ri] = Py[i];
      ri++;
    }
  }

  // Consider the vertical line passing through the middle point
  // calculate the smallest distance dl on left of middle point and
  // dr on right side
  let dl = closestUtil(Px, Pyl, mid);
  let dr = closestUtil(Px.slice(mid), Pyr, n - mid);

  // Find the smaller of two distances
  let d = min(dl, dr);

  // Build an array strip[] that contains points close (closer than d)
  // to the line passing through the middle point
  let strip = newArray(n);
  let j = 0;
  for(let i = 0; i < n; i++) {
    if(Math.abs(Py[i].x - midPoint.x) < d) {
      strip[j] = Py[i];
      j++;
    }
  }

  // Find the closest points in strip.  Return the minimum of d and closest
  // distance is strip[]
  returnstripClosest(strip, j, d);
}

// The main function that finds the smallest distance
// This method mainly uses closestUtil()
functionclosest(P, n) {
  let Px = [...P];
  let Py = [...P];
  Px.sort((a, b) => compareX(a, b));
  Py.sort((a, b) => compareY(a, b));

  // Use recursive function closestUtil() to find the smallest distance
  returnclosestUtil(Px, Py, n);
}

// Driver program to test above functions
functionmain() {
  let P = [
    newPoint(2, 3),
    newPoint(12, 30),
    newPoint(40, 50),
    newPoint(5, 1),
    newPoint(12, 10),
    newPoint(3, 4)
  ];
  let n = P.length;
  console.log(`The smallest distance is ${closest(P, n)}`);
}

main();

