publicclassBinaryTree {
    Node root;
    voidconnect(Node p)
    {
        // initialize queue to hold nodes at same level
        Queue<Node> q = newQueue<Node>();

        q.Enqueue(root); // adding nodes to the queue

        Node temp = null; // initializing prev to null
        while(q.Count > 0) {
            intn = q.Count;
            for(inti = 0; i < n; i++) {
                Node prev = temp;
                temp = q.Dequeue();

                // i > 0 because when i is 0 prev points
                // the last node of previous level,
                // so we skip it
                if(i > 0)
                    prev.nextRight = temp;

                if(temp.left != null)
                    q.Enqueue(temp.left);

                if(temp.right != null)
                    q.Enqueue(temp.right);
            }

            // pointing last node of the nth level to null
            temp.nextRight = null;
        }
    }

