};
// setting right pointer to next right node
/*
             10 ----------> NULL
            /  \
          8 --->2 --------> NULL
         /
        3 ----------------> NULL
        */
voidconnect(node* root)
{
    // Base condition
    if(root == NULL)
        return;
    // Create an empty queue like level order traversal
    queue<node*> q;
    q.push(root);
    while(!q.empty()) {
        // size indicates no. of nodes at current level
        intsize = q.size();
        // for keeping track of previous node
        node* prev = NULL;
        while(size--) {
            node* temp = q.front();
            q.pop();

            if(temp->left)
                q.push(temp->left);

            if(temp->right)
                q.push(temp->right);

            if(prev != NULL)
                prev->nextRight = temp;
            prev = temp;
        }
        prev->nextRight = NULL;
    }
}

