    staticStack<TreeNode> stack = newStack<TreeNode>();

    // Function to build tree using given traversal
    publicTreeNode buildTree(int[] preorder, int[] inorder)
    {
        TreeNode root = null;
        for(intpre = 0, iN = 0; pre < preorder.Length;)
        {
            TreeNode node = null;
            do{
                node = newTreeNode(preorder[pre]);
                if(root == null)
