// C++ program to construct a tree using
// inorder and preorder traversal
#include<bits/stdc++.h>
usingnamespacestd; 

classTreeNode 
{
    public:
    intval;
    TreeNode* left;
    TreeNode* right;
    TreeNode(intx) { val = x; }
};

set<TreeNode*> s;
stack<TreeNode*> st;

// Function to build tree using given traversal
TreeNode* buildTree(intpreorder[], intinorder[],intn)
{

    TreeNode* root = NULL;
    for(intpre = 0, in = 0; pre < n;) 
    {

        TreeNode* node = NULL;
        do
        {
            node = newTreeNode(preorder[pre]);
            if(root == NULL)
            {
                root = node;
            }
            if(st.size() > 0) 
            {
                if(s.find(st.top()) != s.end())
                {
                    s.erase(st.top());
                    st.top()->right = node;
                    st.pop();
                }
                else
                {
                    st.top()->left = node;
                }
            }
            st.push(node);
        } while(preorder[pre++] != inorder[in] && pre < n);

        node = NULL;
        while(st.size() > 0 && in < n && 
                st.top()->val == inorder[in]) 
        {
            node = st.top();
            st.pop();
            in++;
        }

        if(node != NULL) 
        {
            s.insert(node);
            st.push(node);
        }
    }

    returnroot;
}

// Function to print tree in Inorder
voidprintInorder(TreeNode* node)
{
    if(node == NULL)
        return;

    /* first recur on left child */
    printInorder(node->left);

    /* then print the data of node */
    cout << node->val << " ";

    /* now recur on right child */
    printInorder(node->right);
}

// Driver code
intmain()
{
    intin[] = { 9, 8, 4, 2, 10, 5, 10, 1, 6, 3, 13, 12, 7 };
    intpre[] = { 1, 2, 4, 8, 9, 5, 10, 10, 3, 6, 7, 12, 13 };
    intlen = sizeof(in)/sizeof(int);

    TreeNode *root = buildTree(pre, in, len);

    printInorder(root);
    return0;
}

