// A C# program to demonstrate delete in K D tree
usingSystem;
usingSystem.Collections.Generic;

namespacekdtree {
classNode {
    publicint[] point;
    publicNode left;
    publicNode right;
    publicNode(int[] point)
    {
        this.point = point;
        this.left = null;
        this.right = null;
    }
}
classProgram {
    staticintk = 2;
    // Inserts a new node and returns root of modified tree
    // The parameter depth is used to decide axis of
    // comparison
    staticNode insertRec(Node root, int[] point, intdepth)
    {
        // Tree is empty?
        if(root == null) {
            returnnewNode(point);
        }
        // Calculate current dimension (cd) of comparison
        intcd = depth % k;
        // Compare the new point with root on current
        // dimension 'cd' and decide the left or right
        // subtree
        if(point[cd] < root.point[cd]) {
            root.left
                = insertRec(root.left, point, depth + 1);
        }
        else{
            root.right
                = insertRec(root.right, point, depth + 1);
        }
        returnroot;
    }

    // Function to insert a new point with given point in
    // KD Tree and return new root. It mainly uses above
    // recursive function "insertRec()"
    staticNode insert(Node root, int[] point)
    {
        returninsertRec(root, point, 0);
    }
    // A utility function to find minimum of three integers
    staticNode minNode(Node x, Node y, Node z, intd)
    {
        Node res = x;
        if(y != null&& y.point[d] < res.point[d]) {
            res = y;
        }
        if(z != null&& z.point[d] < res.point[d]) {
            res = z;
        }
        returnres;
    }
    // Recursively finds minimum of d'th dimension in KD
    // tree
    // The parameter depth is used to determine current
    // axis.
    staticNode findMinRec(Node root, intd, intdepth)
    {
        // Base cases
        if(root == null) {
            returnnull;
        }
        // Current dimension is computed using current depth
        // and total
        // dimensions (k)
        intcd = depth % k;
        // Compare point with root with respect to cd
        // (Current dimension)
        if(cd == d) {
            if(root.left == null) {
                returnroot;
            }
            returnfindMinRec(root.left, d, depth + 1);
        }
        // If current dimension is different then minimum
        // can be anywhere
        // in this subtree
        returnminNode(
            root, findMinRec(root.left, d, depth + 1),
            findMinRec(root.right, d, depth + 1), d);
    }
    // A wrapper over findMinRec(). Returns minimum of d'th
    // dimension

    staticNode findMin(Node root, intd)
    {
        // Pass current level or depth as 0
        returnfindMinRec(root, d, 0);
    }
    // A utility method to determine if two Points are same
    // in K Dimensional space

    staticboolarePointsSame(int[] point1, int[] point2)
    {
        // Compare individual pointinate values
        for(inti = 0; i < k; ++i) {
            if(point1[i] != point2[i]) {
                returnfalse;
            }
        }

        returntrue;
    }
    // Copies point p2 to p1
    staticvoidcopyPoint(int[] p1, int[] p2)
    {
        for(inti = 0; i < k; i++) {
            p1[i] = p2[i];
        }
    }
    // Function to delete a given point 'point[]' from tree
    // with root
    // as 'root'.  depth is current depth and passed as 0
    // initially. Returns root of the modified tree.
    staticNode deleteNodeRec(Node root, int[] point,
                              intdepth)
    {
        // Given point is not present
        if(root == null) {
            returnnull;
        }
        // Find dimension of current node
        intcd = depth % k;
        // If the point to be deleted is present at root
        if(arePointsSame(root.point, point)) {
            // 2.b) If right child is not NULL
            if(root.right != null) {
                // Find minimum of root's dimension in right
                // subtree
                Node min = findMin(root.right, cd);
                // Copy the minimum to root
                copyPoint(root.point, min.point);
                // Recursively delete the minimum
                root.right = deleteNodeRec(
                    root.right, min.point, depth + 1);
            }
            elseif(root.left != null) {
                Node min = findMin(root.left, cd);
                copyPoint(root.point, min.point);
                root.right = deleteNodeRec(
                    root.left, min.point, depth + 1);
            }
            else// If node to be deleted is leaf node
            {
                root = null;
                returnnull;
            }
            returnroot;
        }
        // 2) If current node doesn't contain point, search
        // downward
        if(point[cd] < root.point[cd]) {
            root.left = deleteNodeRec(root.left, point,
                                      depth + 1);
        }
        else{
            root.right = deleteNodeRec(root.right, point,
                                       depth + 1);
        }
        returnroot;
    }
    // Function to delete a given point from K D Tree with
    // 'root'
    staticNode deleteNode(Node root, int[] point)
    {
        // Pass depth as 0
        returndeleteNodeRec(root, point, 0);
    }
    staticvoidMain(string[] args)
    {
        // Driver program to test above functions
        Node root = null;
        int[][] points = newint[][] {
            newint[] { 30, 40 }, newint[] { 5, 25 },
            newint[] { 70, 70 }, newint[] { 10, 12 },
            newint[] { 50, 30 }, newint[] { 35, 45 }
        };

