        for(inti = 0; i < n; i++) {
            root = insert(root, points[i]);
        }
        // Delete (30, 40);
        root = deleteNode(root, points[0]);
        Console.WriteLine(
            "Root after deletion of (30, 40)");
        Console.WriteLine(root.point[0] + ","
                          + root.point[1]);
    }
}
