            if(sibling.color == COLOR.RED) {
                // sibling red
                parent.color = COLOR.RED;
                sibling.color = COLOR.BLACK;

                if(sibling.isOnLeft())
                    // right case
                    rightRotate(parent);
                else
                    // right case
                    leftRotate(parent);

                fixDoubleBlack(x);
            } else{
                // Sibling black
                if(sibling.hasRedChild()) {
                    // at least 1 red children
                    if(sibling.left != null&& sibling.left.color == COLOR.RED) {
                        if(sibling.isOnLeft()) {
                            // left left
                            sibling.left.color = sibling.color;
                            sibling.color = parent.color;
                            rightRotate(parent);
                        } else{
                            // right right
                            sibling.left.color = parent.color;
                            rightRotate(sibling);
                            leftRotate(parent);
                        }
                    } else{
                        if(sibling.isOnLeft()) {
                            // left right
                            sibling.right.color = parent.color;
                            leftRotate(sibling);
                            rightRotate(parent);
                        } else{
                            // right right
                            sibling.right.color = sibling.color;
                            sibling.color = parent.color;
                            leftRotate(parent);
                        }
                    }
                    parent.color = COLOR.BLACK;
                } else{
                    // 2 black children
                    sibling.color = COLOR.RED;
                    if(parent.color == COLOR.BLACK)
                        fixDoubleBlack(parent);
                    else
                        parent.color = COLOR.BLACK;
                }
            }
        }
    }
    
    // prints level order for given node
    voidlevelOrder(Node x) {
        if(x == null)
            return;
        
        // queue for level order
        Queue<Node> q = newLinkedList<>();
        Node curr;

        q.add(x);

        while(!q.isEmpty()) {
            curr = q.poll();
            // print node value
            System.out.print(curr.val + " ");
            
            // push children to queue
            if(curr.left != null)
                q.add(curr.left);
            if(curr.right != null)
                q.add(curr.right);
        }
    }
    
    // prints inorder recursively
    voidinorder(Node x) {
        if(x == null)
            return;

        inorder(x.left);
        System.out.print(x.val + " ");
        inorder(x.right);
    }
    
    // constructor
    // initialize root
    RBTree() {
        root = null;
    }

    Node getRoot() {
        returnroot;
    }
    
    // searches for given value
    // if found returns the node (used for delete)
    // else returns the last node while traversing (used in insert)
    Node search(intn) {
        Node temp = root;
        while(temp != null) {
            if(n < temp.val) {
                if(temp.left == null)
                    break;
                else
                    temp = temp.left;
            } elseif(n == temp.val) {
                break;
            } else{
                if(temp.right == null)
                    break;
                else
                    temp = temp.right;
            }
        }

        returntemp;
    }
    
    // inserts the given value to tree
    voidinsert(intn) {
        Node newNode = newNode(n);
        if(root == null) {
            // when root is null
            // simply insert value at root
            newNode.color = COLOR.BLACK;
            root = newNode;
        } else{
            Node temp = search(n);
            
            // return if value already exists
            if(temp.val == n)
                return;
                
            // if value is not found, search returns the node
            // where the value is to be inserted
 
            // connect new node to correct node
            newNode.parent = temp;

            if(n < temp.val)
                temp.left = newNode;
            else
                temp.right = newNode;
            
            // fix red red violation if exists
            fixRedRed(newNode);
        }
    }
    
    // utility function that deletes the node with given value
    voiddeleteByVal(intn) {
        if(root == null)
            return;

        Node v = search(n), u;

        if(v.val != n) {
            System.out.println("No node found to delete with value: "+ n);
            return;
        }

        deleteNode(v);
    }
    
    // prints inorder of the tree
    voidprintInOrder() {
        System.out.println("Inorder: ");
        if(root == null)
            System.out.println("Tree is empty");
        else
            inorder(root);
        System.out.println();
    }
    
    // prints level order of the tree
    voidprintLevelOrder() {
        System.out.println("Level order: ");
        if(root == null)
            System.out.println("Tree is empty");
        else
            levelOrder(root);
        System.out.println();
    }
}

