    printf("Popped : %d\n", pop(ms));
    printf("Popped : %d\n", pop(ms));
    printf("Middle Element : %d\n", findMiddle(ms));
      deleteMiddle(ms);
      printf("New Middle Element : %d\n", findMiddle(ms));
