            adj.Add(newList<int>());
    }

    // Function to check if cycle exists
    privateboolisCyclicUtil(inti, bool[] visited,
                              bool[] recStack)
    {
        // Mark the current node as visited and
        // part of recursion stack
        if(recStack[i])
            returntrue;

        if(visited[i])
            returnfalse;

        visited[i] = true;

        recStack[i] = true;
        List<int> children = adj[i];

        foreach(intc inchildren) if(
            isCyclicUtil(c, visited, recStack)) returntrue;

        recStack[i] = false;

        returnfalse;
    }

