// A C++ Program to detect cycle in a graph
#include <bits/stdc++.h>
usingnamespacestd;

classGraph {
    // No. of vertices
    intV;

    // Pointer to an array containing adjacency lists
    list<int>* adj;

    // Used by isCyclic()
    boolisCyclicUtil(intv, boolvisited[], bool* rs);

public:
    Graph(intV);
    voidaddEdge(intv, intw);
    boolisCyclic();
};

Graph::Graph(intV)
{
    this->V = V;
    adj = newlist<int>[V];
}

voidGraph::addEdge(intv, intw)
{
    // Add w to v’s list.
    adj[v].push_back(w);
}

// DFS function to find if a cycle exists
boolGraph::isCyclicUtil(intv, boolvisited[],
                         bool* recStack)
{
    if(visited[v] == false) {
        // Mark the current node as visited
        // and part of recursion stack
        visited[v] = true;
        recStack[v] = true;

        // Recur for all the vertices adjacent to this
        // vertex
        list<int>::iterator i;
        for(i = adj[v].begin(); i != adj[v].end(); ++i) {
            if(!visited[*i]
                && isCyclicUtil(*i, visited, recStack))
                returntrue;
            elseif(recStack[*i])
                returntrue;
        }
    }

    // Remove the vertex from recursion stack
    recStack[v] = false;
    returnfalse;
}

// Returns true if the graph contains a cycle, else false
boolGraph::isCyclic()
{
    // Mark all the vertices as not visited
    // and not part of recursion stack
    bool* visited = newbool[V];
    bool* recStack = newbool[V];
    for(inti = 0; i < V; i++) {
        visited[i] = false;
        recStack[i] = false;
    }

    // Call the recursive helper function
    // to detect cycle in different DFS trees
    for(inti = 0; i < V; i++)
        if(!visited[i]
            && isCyclicUtil(i, visited, recStack))
            returntrue;

    returnfalse;
}

