    {
        intans = 0;
        Node curr = root;

        while(curr != null) {
            if(curr.left == null) {
                curr = curr.right;
            }
            else{
                Node pre = curr.left;
                while(pre.right != null
                       && pre.right != curr) {
                    pre = pre.right;
                }

                if(pre.right == null) {
                    pre.right = curr;
                    curr = curr.left;
