// C++ code to implement the above approach that uses the
// morris traversal algorithm
#include <algorithm>
#include <iostream>

usingnamespacestd;

// A tree node
structNode {
    intdata;
    structNode* left;
    structNode* right;
};

// Create a new node
Node* newNode(intdata)
{
    Node* node = newNode;
    node->data = data;
    node->left = node->right = NULL;
    return(node);
}

// Morris traversal to find the diameter of the binary tree
intfindDiameter(Node* root)
{
    intans = 0;
    Node* curr = root;

    while(curr != NULL) {
        if(curr->left == NULL) {
            curr = curr->right;
        }
        else{
            Node* pre = curr->left;
            while(pre->right != NULL && pre->right != curr)
                pre = pre->right;
            if(pre->right == NULL) {
                pre->right = curr;
                curr = curr->left;
            }
            else{
                pre->right = NULL;
                intleftHeight = 0, rightHeight = 0;
                Node* temp = curr->left;
                while(temp != NULL) {
                    leftHeight++;
                    temp = temp->right;
                }
                temp = curr->right;
                while(temp != NULL) {
                    rightHeight++;
                    temp = temp->left;
                }
                ans = max(ans,
                          leftHeight + rightHeight + 1);
                curr = curr->right;
            }
        }
    }
    returnans;
}

// Driver code
intmain()
{
    // Create the given binary tree
    Node* root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(4);
    root->left->right = newNode(5);

    // Find the diameter of the binary tree using Morris
    // traversal
    intdiameter = findDiameter(root);

    // Print the diameter of the binary tree
    cout << "The diameter of given binary tree is "
         << diameter << endl;

