                     // and free list
        intn, k;
        intfree; // To store beginning index of free list

        //constructor to create k stacks in an array of size n
        KStack(intk1, intn1) 
        {
            // Initialize n and k, and allocate memory for all arrays
            k = k1;
            n = n1;
            arr = newint[n];
            top = newint[k];
            next = newint[n];

            // Initialize all stacks as empty
            for(inti = 0; i < k; i++)
                top[i] = -1;

            // Initialize all spaces as free
            free = 0;
            for(inti = 0; i < n - 1; i++)
                next[i] = i + 1;
            next[n - 1] = -1; // -1 is used to indicate end of free list
        }

        // A utility function to check if there is space available
        booleanisFull() 
        {
            return(free == -1);
        }

        // To push an item in stack number 'sn' where sn is from 0 to k-1
        voidpush(intitem, intsn) 
        {
            // Overflow check
            if(isFull()) 
            {
                System.out.println("Stack Overflow");
                return;
            }

            inti = free; // Store index of first free slot

            // Update index of free slot to index of next slot in free list
            free = next[i];

            // Update next of top and then top for stack number 'sn'
            next[i] = top[sn];
            top[sn] = i;

            // Put the item in array
            arr[i] = item;
        }

        // To pop an element from stack number 'sn' where sn is from 0 to k-1
        intpop(intsn) 
        {
            // Underflow check
            if(isEmpty(sn)) 
            {
                System.out.println("Stack Underflow");
                returnInteger.MAX_VALUE;
            }

            // Find index of top item in stack number 'sn'
            inti = top[sn];

            top[sn] = next[i]; // Change top to store next of previous top

            // Attach the previous top to the beginning of free list
            next[i] = free;
            free = i;

            // Return the previous top item
            returnarr[i];
        }

        // To check whether stack number 'sn' is empty or not
        booleanisEmpty(intsn) 
        {
            return(top[sn] == -1);
        }

    }

    // Driver program
    publicstaticvoidmain(String[] args) 
    {
        // Let us create 3 stacks in an array of size 10
        intk = 3, n = 10;
        
        KStack ks = newKStack(k, n);

        ks.push(15, 2);
        ks.push(45, 2);

        // Let us put some items in stack number 1
        ks.push(17, 1);
        ks.push(49, 1);
        ks.push(39, 1);

        // Let us put some items in stack number 0
        ks.push(11, 0);
        ks.push(9, 0);
        ks.push(7, 0);

        System.out.println("Popped element from stack 2 is "+ ks.pop(2));
        System.out.println("Popped element from stack 1 is "+ ks.pop(1));
        System.out.println("Popped element from stack 0 is "+ ks.pop(0));
    }
