intisFull(Stack* stack)
{
    returnstack->top - 1 == stack->size;
}

intisEmpty(Stack* stack)
{
    returnstack->top == -1;
}

voidpush(Stack* stack, node* node)
{
    if(isFull(stack))
        return;
    stack->array[++stack->top] = node;
}

node* pop(Stack* stack)
{
    if(isEmpty(stack))
        returnNULL;
    returnstack->array[stack->top--];
}

