                ans = i + 1;
            }
        }
        // no index in pref array is less than 0
        if(ans == -1) {
            return0;
        }

        // if at i'th position pref array become 0
        elseif(ans < n) {
            if(pref[ans - 1] + suff[ans] >= 0) {
                returnans;
            }
        }
        // if at n'th position pref array become 0
        elseif(ans == n) {
            if(suff[ans - 1] + pref[ans - 2] >= 0) {
                returnn - 1;
