  {
    publicint[] point = newint[k]; // To store k dimensional point
    publicNode left, right;
  };

  // A method to create a node of K D tree
  staticNode NewNode(int[] arr)
  {
    Node temp = newNode();

    for(inti = 0; i < k; i++)
      temp.point[i] = arr[i];

    temp.left = temp.right = null;
    returntemp;
  }

  // Inserts a new node and returns root of modified tree
  // The parameter depth is used to decide axis of comparison
  staticNode InsertRec(Node root, int[] point, uintdepth)
  {
    // Tree is empty?
    if(root == null)
      returnNewNode(point);

    // Calculate current dimension (cd) of comparison
    uintcd = depth % k;

    // Compare the new point with root on current dimension 'cd'
    // and decide the left or right subtree
    if(point[cd] < root.point[cd])
      root.left = InsertRec(root.left, point, depth + 1);
    else
      root.right = InsertRec(root.right, point, depth + 1);

    returnroot;
  }

  // Function to insert a new point with given point in
  // KD Tree and return new root. It mainly uses above recursive
  // function "InsertRec()"
  staticNode Insert(Node root, int[] point)
  {
    returnInsertRec(root, point, 0);
  }

