    returnMath.Min(x, Math.Min(y, z));
  }

  // Recursively finds minimum of d'th dimension in KD tree
  // The parameter depth is used to determine current axis.
  staticintFindMinRec(Node root, intd, uintdepth)
  {
    // Base cases
    if(root == null)
      returnint.MaxValue;

    // Current dimension is computed using current depth and total
    // dimensions (k)
    uintcd = depth % k;

    // Compare point with root with respect to cd (Current dimension)
    if(cd == d)
    {
      if(root.left == null)
        returnroot.point[d];
      returnMath.Min(root.point[d], FindMinRec(root.left, d, depth + 1));
    }

    // If current dimension is different then minimum can be anywhere
    // in this subtree
    returnMin(root.point[d],
               FindMinRec(root.left, d, depth + 1),
               FindMinRec(root.right, d, depth + 1));
  }

  // A wrapper over FindMinRec(). Returns minimum of d'th dimension
  staticintFindMin(Node root, intd)
  {
    // Pass current level or depth as 0
    returnFindMinRec(root, d, 0);
  }


