classKDTree {
  intk = 2;

  Node newNode(int[] point) {
    returnnewNode(point);
  }

  Node insertRec(Node root, int[] point, intdepth) {
    if(root == null) {
      returnnewNode(point);
    }

    intcd = depth % k;
    if(point[cd] < root.point[cd]) {
      root.left = insertRec(root.left, point, depth + 1);
    } else{
      root.right = insertRec(root.right, point, depth + 1);
    }

    returnroot;
  }

  Node insert(Node root, int[] point) {
    returninsertRec(root, point, 0);
  }

  intmin3(intx, inty, intz) {
    returnMath.min(Math.min(x, y), z);
  }

  intfindMinRec(Node root, intd, intdepth) {
    if(root == null) {
      returnInteger.MAX_VALUE;
    }

    intcd = depth % k;
    if(cd == d) {
      if(root.left == null) {
        returnroot.point[d];
      }
      returnmin3(root.point[d], findMinRec(root.left, d, depth + 1), findMinRec(root.right, d, depth + 1));
    }

    returnmin3(root.point[d], findMinRec(root.left, d, depth + 1), findMinRec(root.right, d, depth + 1));
  }

  intfindMin(Node root, intd) {
    returnfindMinRec(root, d, 0);
  }

