usingSystem;

publicclassGFG {
    /* Return true if arr2[] is a subset of arr1[] */
    staticboolisSubset(int[] arr1, int[] arr2, intm,
                         intn)
    {
        inti = 0;

        sort(arr1, 0, m - 1);
        for(i = 0; i < n; i++) {
            if(binarySearch(arr1, 0, m - 1, arr2[i]) == -1)
                returnfalse;
        }

        /* If we reach here then all elements of arr2[]
          are present in arr1[] */
        returntrue;
    }

    /* FOLLOWING FUNCTIONS ARE ONLY FOR SEARCHING AND
     * SORTING PURPOSE */
    /* Standard Binary Search function*/
    staticintbinarySearch(int[] arr, intlow, inthigh,
                            intx)
    {
        if(high >= low) {
            intmid = (low + high) / 2;

            /* Check if arr[mid] is the first
            occurrence of x.
            arr[mid] is first occurrence if x
            is one of the following
            is true:
            (i)  mid == 0 and arr[mid] == x
            (ii) arr[mid-1] < x and arr[mid] == x
         */
            if((mid == 0 || x > arr[mid - 1])
                && (arr[mid] == x))
                returnmid;
            elseif(x > arr[mid])
                returnbinarySearch(arr, (mid + 1), high,
                                    x);
            else
                returnbinarySearch(arr, low, (mid - 1), x);
        }
        return-1;
    }

    /* This function takes last element as pivot,
       places the pivot element at its correct
       position in sorted array, and places all
       smaller (smaller than pivot) to left of
       pivot and all greater elements to right
       of pivot */
    staticintpartition(int[] arr, intlow, inthigh)
    {
        intpivot = arr[high];
        inti = (low - 1);
        inttemp = 0;
        for(intj = low; j < high; j++) {
            // If current element is smaller than or
            // equal to pivot
            if(arr[j] <= pivot) {
                i++;
                // swap arr[i] and arr[j]
                temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }

        // swap arr[i+1] and arr[high] (or pivot)
        temp = arr[i + 1];
        arr[i + 1] = arr[high];
        arr[high] = temp;

        returni + 1;
    }

    /* The main function that implements QuickSort()
      arr[] --> Array to be sorted,
      low  --> Starting index,
      high  --> Ending index */
    staticvoidsort(int[] arr, intlow, inthigh)
    {
        if(low < high) {
            /* pi is partitioning index, arr[pi] is
              now at right place */
            intpi = partition(arr, low, high);

            // Recursively sort elements before
            // partition and after partition
            sort(arr, low, pi - 1);
            sort(arr, pi + 1, high);
        }
    }

