{
    structnode* root = newNode(8);

    root->left = newNode(4);
    root->right = newNode(12);

    root->left->left = newNode(2);
    root->left->right = newNode(6);

    root->right->left = newNode(10);
    root->right->right = newNode(14);

    for(inti = 0; i < 16; i++)
        printf("%d %d\n", i, Ceil(root, i));

    return0;
}

