/* C program for solution of Hamiltonian Cycle problem
   using backtracking */
#include<stdio.h>

// Number of vertices in the graph
#define V 5

voidprintSolution(intpath[]);

/* A utility function to check if the vertex v can be added at
   index 'pos' in the Hamiltonian Cycle constructed so far (stored
   in 'path[]') */
boolisSafe(intv, boolgraph[V][V], intpath[], intpos)
{
    /* Check if this vertex is an adjacent vertex of the previously
       added vertex. */
    if(graph [ path[pos-1] ][ v ] == 0)
        returnfalse;

    /* Check if the vertex has already been included.
      This step can be optimized by creating an array of size V */
    for(inti = 0; i < pos; i++)
        if(path[i] == v)
            returnfalse;

    returntrue;
}

/* A recursive utility function to solve hamiltonian cycle problem */
boolhamCycleUtil(boolgraph[V][V], intpath[], intpos)
{
    /* base case: If all vertices are included in Hamiltonian Cycle */
    if(pos == V)
    {
        // And if there is an edge from the last included vertex to the
        // first vertex
        if( graph[ path[pos-1] ][ path[0] ] == 1 )
           returntrue;
        else
          returnfalse;
    }

    // Try different vertices as a next candidate in Hamiltonian Cycle.
    // We don't try for 0 as we included 0 as starting point in hamCycle()
    for(intv = 1; v < V; v++)
    {
        /* Check if this vertex can be added to Hamiltonian Cycle */
        if(isSafe(v, graph, path, pos))
        {
            path[pos] = v;

            /* recur to construct rest of the path */
            if(hamCycleUtil (graph, path, pos+1) == true)
                returntrue;

            /* If adding vertex v doesn't lead to a solution,
               then remove it */
            path[pos] = -1;
        }
    }

    /* If no vertex can be added to Hamiltonian Cycle constructed so far,
       then return false */
    returnfalse;
}

/* This function solves the Hamiltonian Cycle problem using Backtracking.
  It mainly uses hamCycleUtil() to solve the problem. It returns false
  if there is no Hamiltonian Cycle possible, otherwise return true and
  prints the path. Please note that there may be more than one solutions,
  this function prints one of the feasible solutions. */
boolhamCycle(boolgraph[V][V])
{
    int*path = newint[V];
    for(inti = 0; i < V; i++)
        path[i] = -1;

    /* Let us put vertex 0 as the first vertex in the path. If there is
       a Hamiltonian Cycle, then the path can be started from any point
       of the cycle as the graph is undirected */
    path[0] = 0;
    if( hamCycleUtil(graph, path, 1) == false)
    {
        printf("\nSolution does not exist");
        returnfalse;
    }

    printSolution(path);
    returntrue;
}

/* A utility function to print solution */
voidprintSolution(intpath[])
{
    printf("Solution Exists:"
            " Following is one Hamiltonian Cycle \n");
    for(inti = 0; i < V; i++)
        printf(" %d ", path[i]);

    // Let us print the first vertex again to show the complete cycle
    printf(" %d ", path[0]);
    printf("\n");
}

