  }

  publicclassline {
    publicPoint p1, p2;
    publicline(Point p1, Point p2)
    {
      this.p1=p1;
      this.p2=p2;
    }
  }

  staticintonLine(line l1, Point p)
  {
    // Check whether p is on the line or not
    if(p.x <= Math.Max(l1.p1.x, l1.p2.x)
        && p.x >= Math.Min(l1.p1.x, l1.p2.x)
        && (p.y <= Math.Max(l1.p1.y, l1.p2.y)
            && p.y >= Math.Min(l1.p1.y, l1.p2.y)))
      return1;

    return0;
  }

  staticintdirection(Point a, Point b, Point c)
  {
    intval = (b.y - a.y) * (c.x - b.x)
      - (b.x - a.x) * (c.y - b.y);

    if(val == 0)

      // Collinear
      return0;

    elseif(val < 0)

      // Anti-clockwise direction
      return2;

    // Clockwise direction
    return1;
  }

  staticintisIntersect(line l1, line l2)
  { 
    // Four direction for two lines and points of other line
    intdir1 = direction(l1.p1, l1.p2, l2.p1);
    intdir2 = direction(l1.p1, l1.p2, l2.p2);
    intdir3 = direction(l2.p1, l2.p2, l1.p1);
    intdir4 = direction(l2.p1, l2.p2, l1.p2);

    // When intersecting
    if(dir1 != dir2 && dir3 != dir4)
      return1;

    // When p2 of line2 are on the line1
    if(dir1 == 0 && onLine(l1, l2.p1)==1)
      return1;

    // When p1 of line2 are on the line1
    if(dir2 == 0 && onLine(l1, l2.p2)==1)
      return1;

    // When p2 of line1 are on the line2
    if(dir3 == 0 && onLine(l2, l1.p1)==1)
      return1;

    // When p1 of line1 are on the line2
    if(dir4 == 0 && onLine(l2, l1.p2)==1)
      return1;

    return0;
  }

  staticintcheckInside(Point[] poly, intn, Point p)
  {

    // When polygon has less than 3 edge, it is not polygon
    if(n < 3)
      return0;

    // Create a point at infinity, y is same as point p
    Point pt=newPoint(9999, p.y);
    line exline = newline(p,pt); 
