// minimum value node from heap 
structMinHeapNode* extractMin(structMinHeap* minHeap) 
 
{ 
 
    structMinHeapNode* temp = minHeap->array[0]; 
    minHeap->array[0] = minHeap->array[minHeap->size - 1]; 
 
    --minHeap->size; 
    minHeapify(minHeap, 0); 
 
    returntemp; 
} 
 
