            Console.Write("Stack Overflow"
                          + " By element : "+ x + "\n"); 
            return; 
        } 
    } 
 
    // Method to push an element 
    // x to stack2 
    publicvoidpush2(intx) 
    { 
 
        // There is at least one empty 
        // space for new element 
        if(top2 < size - 1) { 
            top2++; 
            arr[top2] = x; 
        } 
        else{ 
            Console.Write("Stack Overflow"
                          + " By element : "+ x + "\n"); 
            return; 
        } 
    } 
 
