usingSystem;
usingSystem.Collections.Generic;

publicstructItem
{
    publicfloatweight;
    publicintvalue;
}

publicstructNode
{
    publicintlevel;
    publicintprofit;
    publicintbound;
    publicfloatweight;
}

publicclassKnapsack
{
    publicstaticboolCompare(Item a, Item b)
    {
        doubler1 = (double)a.value / a.weight;
        doubler2 = (double)b.value / b.weight;
        returnr1 > r2;
    }

    publicstaticintBound(Node u, intn, intW, Item[] arr)
    {
        if(u.weight >= W)
            return0;

        intprofitBound = u.profit;
        intj = u.level + 1;
        inttotWeight = (int)u.weight;

        while(j < n && totWeight + (int)arr[j].weight <= W)
        {
            totWeight += (int)arr[j].weight;
            profitBound += arr[j].value;
            j++;
        }

        if(j < n)
            profitBound += (int)((W - totWeight) * arr[j].value / arr[j].weight);

        returnprofitBound;
    }

    publicstaticintKnapsackSolution(intW, Item[] arr, intn)
    {
        Array.Sort<Item>(arr, Compare);

        Queue<Node> q = newQueue<Node>();
        Node u, v;
        intmaxProfit = 0;

        u.level = -1;
        u.profit = 0;
        u.weight = 0;
        q.Enqueue(u);

        while(q.Count > 0)
        {
            u = q.Dequeue();

            if(u.level == -1)
                v.level = 0;

            if(u.level == n - 1)
                continue;

            v.level = u.level + 1;
            v.weight = u.weight + arr[v.level].weight;
            v.profit = u.profit + arr[v.level].value;

            if(v.weight <= W && v.profit > maxProfit)
                maxProfit = v.profit;

            v.bound = Bound(v, n, W, arr);

            if(v.bound > maxProfit)
                q.Enqueue(v);

            v.weight = u.weight;
            v.profit = u.profit;
            v.bound = Bound(v, n, W, arr);

            if(v.bound > maxProfit)
                q.Enqueue(v);
        }

        returnmaxProfit;
    }

    publicstaticvoidMain(string[] args)
    {
        intW = 10;
        Item[] arr = newItem[5] { newItem { weight = 2, value = 40 },
                                   newItem { weight = 3.14f, value = 50 },
                                   newItem { weight = 1.98f, value = 100 },
                                   newItem { weight = 5, value = 95 },
                                   newItem { weight = 3, value = 30 } };
        intn = arr.Length;

        Console.WriteLine("Maximum possible profit = {0}", KnapsackSolution(W, arr, n));
    }
}

