const arr = [
{ weight: 2, value: 40 },
{ weight: 3.14, value: 50 },
{ weight: 1.98, value: 100 },
{ weight: 5, value: 95 },
{ weight: 3, value: 30 },
];
const n = arr.length;

console.log(`Maximum possible profit = ${knapsack(W, arr, n)}`);
}
