publicclassInOrderTraversal
{
    // Function to perform iterative in-order traversal
    publicstaticList<int> InOrderTrav(Node curr)
    {
        List<int> inOrder = newList<int>();
        Stack<Node> stack = newStack<Node>();
        
        while(true)
        {
            // Traverse left subtree until current node is null
            if(curr != null)
            {
                stack.Push(curr);
                curr = curr.left;
            }
            else
            {
                // If current node is null, pop a node from the stack,
                // add its data to the in-order list, and traverse its right subtree
                if(stack.Count == 0)
                    break;
                
                curr = stack.Pop();
                inOrder.Add(curr.data);
                curr = curr.right;
            }
        }
        
        returninOrder;
    }

