classRedBlackTree {
private:
    // Node creating subclass
    structNode {
        intdata;
        Node* left;
        Node* right;
        charcolour;
        Node* parent;

        Node(intdata) : data(data), left(nullptr), right(nullptr), colour('R'), parent(nullptr) {}
    };

    Node* root;
    boolll; // Left-Left Rotation flag
    boolrr; // Right-Right Rotation flag
    boollr; // Left-Right Rotation flag
    boolrl; // Right-Left Rotation flag

    // Function to perform Left Rotation
    Node* rotateLeft(Node* node) {
        Node* x = node->right;
        Node* y = x->left;
        x->left = node;
        node->right = y;
        node->parent = x;
        if(y != nullptr)
            y->parent = node;
        returnx;
    }

    // Function to perform Right Rotation
    Node* rotateRight(Node* node) {
        Node* x = node->left;
        Node* y = x->right;
        x->right = node;
        node->left = y;
        node->parent = x;
        if(y != nullptr)
            y->parent = node;
        returnx;
    }

    // Helper function for insertion
    Node* insertHelp(Node* root, intdata) {
        boolf = false; // Flag to check RED-RED conflict

        if(root == nullptr)
            returnnewNode(data);
        elseif(data < root->data) {
            root->left = insertHelp(root->left, data);
            root->left->parent = root;
            if(root != this->root) {
                if(root->colour == 'R'&& root->left->colour == 'R')
                    f = true;
            }
        } else{
            root->right = insertHelp(root->right, data);
            root->right->parent = root;
            if(root != this->root) {
                if(root->colour == 'R'&& root->right->colour == 'R')
                    f = true;
            }
        }

        // Perform rotations
        if(ll) {
            root = rotateLeft(root);
            root->colour = 'B';
            root->left->colour = 'R';
            ll = false;
        } elseif(rr) {
            root = rotateRight(root);
            root->colour = 'B';
            root->right->colour = 'R';
            rr = false;
        } elseif(rl) {
            root->right = rotateRight(root->right);
            root->right->parent = root;
            root = rotateLeft(root);
            root->colour = 'B';
            root->left->colour = 'R';
            rl = false;
        } elseif(lr) {
            root->left = rotateLeft(root->left);
            root->left->parent = root;
            root = rotateRight(root);
            root->colour = 'B';
            root->right->colour = 'R';
            lr = false;
        }

        // Handle RED-RED conflicts
        if(f) {
            if(root->parent->right == root) {
                if(root->parent->left == nullptr || root->parent->left->colour == 'B') {
                    if(root->left != nullptr && root->left->colour == 'R')
                        rl = true;
                    elseif(root->right != nullptr && root->right->colour == 'R')
                        ll = true;
                } else{
                    root->parent->left->colour = 'B';
                    root->colour = 'B';
                    if(root->parent != this->root)
                        root->parent->colour = 'R';
                }
            } else{
                if(root->parent->right == nullptr || root->parent->right->colour == 'B') {
                    if(root->left != nullptr && root->left->colour == 'R')
                        rr = true;
                    elseif(root->right != nullptr && root->right->colour == 'R')
                        lr = true;
                } else{
                    root->parent->right->colour = 'B';
                    root->colour = 'B';
                    if(root->parent != this->root)
                        root->parent->colour = 'R';
                }
            }
            f = false;
        }
        returnroot;
    }

    // Helper function to perform Inorder Traversal
    voidinorderTraversalHelper(Node* node) {
        if(node != nullptr) {
            inorderTraversalHelper(node->left);
            std::cout << node->data << " ";
            inorderTraversalHelper(node->right);
        }
    }

    // Helper function to print the tree
    voidprintTreeHelper(Node* root, intspace) {
        if(root != nullptr) {
            space += 10;
            printTreeHelper(root->right, space);
            std::cout << std::endl;
            for(inti = 10; i < space; i++)
                std::cout << " ";
            std::cout << root->data << std::endl;
            printTreeHelper(root->left, space);
        }
    }

public:
    RedBlackTree() : root(nullptr), ll(false), rr(false), lr(false), rl(false) {}

    // Function to insert data into the tree
    voidinsert(intdata) {
        if(root == nullptr) {
            root = newNode(data);
            root->colour = 'B';
        } else
            root = insertHelp(root, data);
    }

    // Function to perform Inorder Traversal of the tree
    voidinorderTraversal() {
        inorderTraversalHelper(root);
    }

    // Function to print the tree
    voidprintTree() {
        printTreeHelper(root, 0);
    }
