// This code is adopted from http://algs4.cs.princeton.edu/33balanced/SplayBST.java.html
#include<stdio.h>
#include<stdlib.h>

// An AVL tree node
structnode
{
    intkey;
    structnode *left, *right;
};

/* Helper function that allocates a new node with the given key and
    NULL left and right pointers. */
structnode* newNode(intkey)
{
    structnode* node = (structnode*)malloc(sizeof(structnode));
    node->key   = key;
    node->left  = node->right  = NULL;
    return(node);
}

// A utility function to right rotate subtree rooted with y
// See the diagram given above.
structnode *rightRotate(structnode *x)
{
    structnode *y = x->left;
    x->left = y->right;
    y->right = x;
    returny;
}

// A utility function to left rotate subtree rooted with x
// See the diagram given above.
structnode *leftRotate(structnode *x)
{
    structnode *y = x->right;
    x->right = y->left;
    y->left = x;
    returny;
}

// This function brings the key at root if key is present in tree.
// If key is not present, then it brings the last accessed item at
// root.  This function modifies the tree and returns the new root
structnode *splay(structnode *root, intkey)
{
    // Base cases: root is NULL or key is present at root
    if(root == NULL || root->key == key)
        returnroot;

    // Key lies in left subtree
    if(root->key > key)
    {
        // Key is not in tree, we are done
        if(root->left == NULL) returnroot;

        // Zig-Zig (Left Left)
        if(root->left->key > key)
        {
            // First recursively bring the key as root of left-left
            root->left->left = splay(root->left->left, key);

            // Do first rotation for root, second rotation is done after else
            root = rightRotate(root);
        }
        elseif(root->left->key < key) // Zig-Zag (Left Right)
        {
            // First recursively bring the key as root of left-right
            root->left->right = splay(root->left->right, key);

            // Do first rotation for root->left
            if(root->left->right != NULL)
                root->left = leftRotate(root->left);
        }

        // Do second rotation for root
        return(root->left == NULL)? root: rightRotate(root);
    }
    else// Key lies in right subtree
    {
        // Key is not in tree, we are done
        if(root->right == NULL) returnroot;

        // Zig-Zag (Right Left)
        if(root->right->key > key)
        {
            // Bring the key as root of right-left
            root->right->left = splay(root->right->left, key);

            // Do first rotation for root->right
            if(root->right->left != NULL)
                root->right = rightRotate(root->right);
        }
        elseif(root->right->key < key)// Zag-Zag (Right Right)
        {
            // Bring the key as root of right-right and do first rotation
            root->right->right = splay(root->right->right, key);
            root = leftRotate(root);
        }

        // Do second rotation for root
        return(root->right == NULL)? root: leftRotate(root);
    }
}

// Function to insert a new key k in splay tree with given root
structnode *insert(structnode *root, intk)
{
    // Simple Case: If tree is empty
    if(root == NULL) returnnewNode(k);

    // Bring the closest leaf node to root
    root = splay(root, k);

    // If key is already present, then return
    if(root->key == k) returnroot;

    // Otherwise allocate memory for new node
    structnode *newnode  = newNode(k);

    // If root's key is greater, make root as right child
    // of newnode and copy the left child of root to newnode
    if(root->key > k)
    {
        newnode->right = root;
        newnode->left = root->left;
        root->left = NULL;
    }

    // If root's key is smaller, make root as left child
    // of newnode and copy the right child of root to newnode
    else
    {
        newnode->left = root;
        newnode->right = root->right;
        root->right = NULL;
    }

    returnnewnode; // newnode becomes new root
}

// A utility function to print preorder traversal of the tree.
// The function also prints height of every node
voidpreOrder(structnode *root)
{
    if(root != NULL)
    {
        printf("%d ", root->key);
        preOrder(root->left);
        preOrder(root->right);
    }
}

/* Driver program to test above function*/
intmain()
{
    structnode *root = newNode(100);
    root->left = newNode(50);
    root->right = newNode(200);
    root->left->left = newNode(40);
    root->left->left->left = newNode(30);
    root->left->left->left->left = newNode(20);
    root = insert(root, 25);
    printf("Preorder traversal of the modified Splay tree is \n");
    preOrder(root);
    return0;
}

