    constructor(n) {
        this.rank = newArray(n);
        this.parent = newArray(n);
        this.n = n;
        this.makeSet();
    }

    makeSet() {
        for(let i = 0; i < this.n; i++) {
            this.parent[i] = i;
        }
    }

    find(x) {
        if(this.parent[x] !== x) {
            this.parent[x] = this.find(this.parent[x]);
        }
        returnthis.parent[x];
    }

    Union(x, y) {
        let xset = this.find(x);
        let yset = this.find(y);

        if(xset === yset) return;

        if(this.rank[xset] < this.rank[yset]) {
            this.parent[xset] = yset;
