// Program to solve Job Assignment problem
// using Branch and Bound
#include <bits/stdc++.h>
usingnamespacestd;
#define N 4

// state space tree node
structNode
{
    // stores parent node of current node
    // helps in tracing path when answer is found
    Node* parent;

    // contains cost for ancestors nodes
    // including current node
    intpathCost;

    // contains least promising cost
    intcost;

    // contain worker number
    intworkerID;

    // contains Job ID
    intjobID;

    // Boolean array assigned will contains
    // info about available jobs
    boolassigned[N];
};

// Function to allocate a new search tree node
// Here Person x is assigned to job y
Node* newNode(intx, inty, boolassigned[],
              Node* parent)
{
    Node* node = newNode;

    for(intj = 0; j < N; j++)
        node->assigned[j] = assigned[j];
    node->assigned[y] = true;

    node->parent = parent;
    node->workerID = x;
    node->jobID = y;

    returnnode;
}

// Function to calculate the least promising cost
// of node after worker x is assigned to job y.
intcalculateCost(intcostMatrix[N][N], intx,
                  inty, boolassigned[])
{
    intcost = 0;

    // to store unavailable jobs
    boolavailable[N] = {true};

    // start from next worker
    for(inti = x + 1; i < N; i++)
    {
        intmin = INT_MAX, minIndex = -1;

        // do for each job
        for(intj = 0; j < N; j++)
        {
            // if job is unassigned
            if(!assigned[j] && available[j] &&
                costMatrix[i][j] < min)
            {
                // store job number
                minIndex = j;

                // store cost
                min = costMatrix[i][j];
            }
        }

        // add cost of next worker
        cost += min;

        // job becomes unavailable
        available[minIndex] = false;
    }

    returncost;
}

// Comparison object to be used to order the heap
structcomp
{
    booloperator()(constNode* lhs,
                   constNode* rhs) const
    {
        returnlhs->cost > rhs->cost;
    }
};

// print Assignments
voidprintAssignments(Node *min)
{
    if(min->parent==NULL)
        return;

    printAssignments(min->parent);
    cout << "Assign Worker "<< char(min->workerID + 'A')
         << " to Job "<< min->jobID << endl;

}

// Finds minimum cost using Branch and Bound.
intfindMinCost(intcostMatrix[N][N])
{
    // Create a priority queue to store live nodes of
    // search tree;
    priority_queue<Node*, std::vector<Node*>, comp> pq;

    // initialize heap to dummy node with cost 0
    boolassigned[N] = {false};
    Node* root = newNode(-1, -1, assigned, NULL);
    root->pathCost = root->cost = 0;
    root->workerID = -1;

    // Add dummy node to list of live nodes;
    pq.push(root);

    // Finds a live node with least cost,
    // add its childrens to list of live nodes and
    // finally deletes it from the list.
    while(!pq.empty())
    {
      // Find a live node with least estimated cost
      Node* min = pq.top();

      // The found node is deleted from the list of
      // live nodes
      pq.pop();

      // i stores next worker
      inti = min->workerID + 1;

      // if all workers are assigned a job
      if(i == N)
      {
          printAssignments(min);
          returnmin->cost;
      }

      // do for each job
      for(intj = 0; j < N; j++)
      {
        // If unassigned
        if(!min->assigned[j])
        {
          // create a new tree node
          Node* child = newNode(i, j, min->assigned, min);

          // cost for ancestors nodes including current node
          child->pathCost = min->pathCost + costMatrix[i][j];

          // calculate its lower bound
          child->cost = child->pathCost +
            calculateCost(costMatrix, i, j, child->assigned);

          // Add child to list of live nodes;
          pq.push(child);
        }
