        KthLargest(arr, 0, N - 1, k, N);

        // Print K Largest numbers
        Console.Write($"{k} largest elements are: ");
        for(int i = N - 1; i >= N - k; i--)
            Console.Write($"{arr[i]} ");

        Console.WriteLine();
    }
}

