// Class containing left and right child of current
// node and key value
classNode {
    intdata;
    Node left, right;
    publicNode(intitem)
    {
        data = item;
        left = right = null;
    }
}

classBinaryTree {
    
    // Root of the Binary Tree
    Node root;

    publicBinaryTree() { root = null; }

    // Function to print level order traversal of tree
    voidprintLevelOrder()
    {
        inth = height(root);
        inti;
        for(i = 1; i <= h; i++)
            printCurrentLevel(root, i);
    }

    // Compute the "height" of a tree -- the number of
    // nodes along the longest path from the root node
    // down to the farthest leaf node.
    intheight(Node root)
    {
        if(root == null)
            return0;
        else{
            
            // Compute  height of each subtree
            intlheight = height(root.left);
            intrheight = height(root.right);

            // use the larger one
            if(lheight > rheight)
                return(lheight + 1);
            else
                return(rheight + 1);
        }
    }

    // Print nodes at the current level
    voidprintCurrentLevel(Node root, intlevel)
    {
        if(root == null)
            return;
        if(level == 1)
            System.out.print(root.data + " ");
        elseif(level > 1) {
            printCurrentLevel(root.left, level - 1);
            printCurrentLevel(root.right, level - 1);
        }
    }

