/* C# Naive recursive implementation of LCS problem */
usingSystem;

classGFG {

    /* Returns length of LCS for X[0..m-1], Y[0..n-1] */
    staticintlcs(char[] X, char[] Y, intm, intn,
                   int[, ] L)
    {
        if(m == 0 || n == 0)
            return0;

        if(L[m, n] != -1)
            returnL[m, n];

        if(X[m - 1] == Y[n - 1]) {
            L[m, n] = 1 + lcs(X, Y, m - 1, n - 1, L);
            returnL[m, n];
        }

        L[m, n] = max(lcs(X, Y, m, n - 1, L),
                      lcs(X, Y, m - 1, n, L));
        returnL[m, n];
    }

    /* Utility function to get max of 2 integers */
    staticintmax(inta, intb) { return(a > b) ? a : b; }

    publicstaticvoidMain()
    {
        String s1 = "AGGTAB";
        String s2 = "GXTXAYB";

        char[] X = s1.ToCharArray();
        char[] Y = s2.ToCharArray();
        intm = X.Length;
        intn = Y.Length;
        int[, ] L = newint[m + 1, n + 1];
        for(inti = 0; i <= m; i++) {
            for(intj = 0; j <= n; j++) {
                L[i, j] = -1;
            }
        }
        Console.Write("Length of LCS is"
                      + " "+ lcs(X, Y, m, n, L));
    }
}

