    // lis() returns the length of the longest increasing
    // subsequence in arr[] of size n
    staticintlis(int[] arr, intn)
    {
        int[] lis = newint[n];
        inti, j, max = 0;

        // Initialize LIS values for all indexes
        for(i = 0; i < n; i++)
            lis[i] = 1;

