// C# program to implement the approach

usingSystem;
usingSystem.Collections.Generic;

classLRUCache {
    // store keys of cache
    privateList<int> doublyQueue;

    // store references of key in cache
    privateHashSet<int> hashSet;

    // maximum capacity of cache
    privateintCACHE_SIZE;

    publicLRUCache(intcapacity)
    {
        doublyQueue = newList<int>();
        hashSet = newHashSet<int>();
        CACHE_SIZE = capacity;
    }

    /* Refer the page within the LRU cache */
    publicvoidRefer(intpage)
    {
        if(!hashSet.Contains(page)) {
            if(doublyQueue.Count == CACHE_SIZE) {
                intlast
                    = doublyQueue[doublyQueue.Count - 1];
                doublyQueue.RemoveAt(doublyQueue.Count - 1);
                hashSet.Remove(last);
            }
        }
        else{
            /* The found page may not be always the last
               element, even if it's an intermediate
               element that needs to be removed and added
               to the start of the Queue */
            doublyQueue.Remove(page);
        }
        doublyQueue.Insert(0, page);
        hashSet.Add(page);
    }

    // display contents of cache
    publicvoidDisplay()
    {
        foreach(intpage indoublyQueue)
        {
            Console.Write(page + " ");
        }
    }

    // Driver code
    staticvoidMain(string[] args)
    {
        LRUCache cache = newLRUCache(4);
        cache.Refer(1);
        cache.Refer(2);
        cache.Refer(3);
        cache.Refer(1);
        cache.Refer(4);
        cache.Refer(5);
        cache.Display();
    }
