/* We can use Java inbuilt Deque as a double
   ended queue to store the cache keys, with
   the descending time of reference from front
   to back and a set container to check presence
   of a key. But remove a key from the Deque using
   remove(), it takes O(N) time. This can be
   optimized by storing a reference (iterator) to
   each key in a hash map. */
importjava.util.Deque;
importjava.util.HashSet;
importjava.util.Iterator;
importjava.util.LinkedList;

publicclassLRUCache {

    // store keys of cache
    privateDeque<Integer> doublyQueue;

    // store references of key in cache
    privateHashSet<Integer> hashSet;

    // maximum capacity of cache
    privatefinalintCACHE_SIZE;

    LRUCache(intcapacity)
    {
        doublyQueue = newLinkedList<>();
        hashSet = newHashSet<>();
        CACHE_SIZE = capacity;
    }

    /* Refer the page within the LRU cache */
    publicvoidrefer(intpage)
    {
        if(!hashSet.contains(page)) {
            if(doublyQueue.size() == CACHE_SIZE) {
                intlast = doublyQueue.removeLast();
                hashSet.remove(last);
            }
        }
        else{ /* The found page may not be always the last
                element, even if it's an intermediate
                element that needs to be removed and added
                to the start of the Queue */
            doublyQueue.remove(page);
        }
        doublyQueue.push(page);
        hashSet.add(page);
    }

    // display contents of cache
    publicvoiddisplay()
    {
        Iterator<Integer> itr = doublyQueue.iterator();
        while(itr.hasNext()) {
            System.out.print(itr.next() + " ");
        }
    }

      // Driver code
    publicstaticvoidmain(String[] args)
    {
        LRUCache cache = newLRUCache(4);
        cache.refer(1);
        cache.refer(2);
        cache.refer(3);
        cache.refer(1);
        cache.refer(4);
        cache.refer(5);
        cache.display();
    }
}
