// JS code to implement the approach
class LRUCache {
  constructor(n) {
    this.csize = n;
    this.dq = [];
    this.ma = newMap();
  }

  refer(x) {
    if(!this.ma.has(x)) {
      if(this.dq.length === this.csize) {
        const last = this.dq[this.dq.length - 1];
        this.dq.pop();
        this.ma.delete(last);
      }
    } else{
      this.dq.splice(this.dq.indexOf(x), 1);
    }

    this.dq.unshift(x);
    this.ma.set(x, 0);
  }

  display() {
    console.log(this.dq);
  }
}

const cache = newLRUCache(4);

cache.refer(1);
cache.refer(2);
cache.refer(3);
cache.refer(1);
cache.refer(4);
cache.refer(5);
cache.display();

