// C# program to demonstrate insert 
// operation in binary search tree.
usingSystem;

publicclassNode
{
    publicintkey;
    publicintc = 0;
    publicNode left,right;
     
}

classGFG{
    
staticintma = 0;

// A utility function to create a 
// new BST node
staticNode newNode(intitem)
{
    Node temp = newNode();
    temp.key = item;
    temp.c = 1;
    temp.left = temp.right = null;
    returntemp;
}
 
// A utility function to insert a new node
// with given key in BST
staticNode insert(Node node, intkey)
{
    
    // If the tree is empty, 
    // return a new node
    if(node == null) 
    {
        if(ma == 0)
            ma = 1;
 
        returnnewNode(key);
    }
     
    // Otherwise, recur down the tree
    if(key < node.key)
        node.left = insert(node.left, key);
    elseif(key > node.key)
        node.right = insert(node.right, key);
    else
        node.c++;
 
    // Find the max count
    ma = Math.Max(ma, node.c);
  
    // Return the (unchanged) node pointer
    returnnode;
}
 
// A utility function to do inorder
// traversal of BST
staticvoidinorder(Node root, ints)
{
    if(root != null) 
    {
        inorder(root.left, s);
 
        if(root.c > (s / 2))
            Console.WriteLine(root.key + "\n");
 
        inorder(root.right, s);
    }
}

// Driver Code
staticpublicvoidMain()
{
    int[] a = { 1, 3, 3, 3, 2 };
    intsize = a.Length;
    Node root = null;
    
    for(inti = 0; i < size; i++) 
    {
        root = insert(root, a[i]);
    }
    
    // Function call
    if(ma > (size / 2))
        inorder(root, size);
    else
        Console.WriteLine("No majority element\n");
}
}

