// Program to find maximum sum subarray
// in a given 2D array
#include <limits.h>
#include <stdio.h>
#include <string.h>
#define ROW 4
#define COL 5

// Implementation of Kadane's algorithm
// for 1D array. The function returns the
// maximum sum and stores starting and
// ending indexes of the maximum sum subarray
// at addresses pointed by start and finish
// pointers respectively.
intkadane(int* arr, int* start, int* finish, intn)
{
    // initialize sum, maxSum and
    intsum = 0, maxSum = INT_MIN, i;

    // Just some initial value to check for all negative
    // values case
    *finish = -1;

    // local variable
    intlocal_start = 0;

    for(i = 0; i < n; ++i) {
        sum += arr[i];
        if(sum < 0) {
            sum = 0;
            local_start = i + 1;
        }
        elseif(sum > maxSum) {
            maxSum = sum;
            *start = local_start;
            *finish = i;
        }
    }

    // There is at-least one non-negative number
    if(*finish != -1)
        returnmaxSum;

    // Special Case: When all numbers in arr[]
    // are negative
    maxSum = arr[0];
    *start = *finish = 0;

    // Find the maximum element in array
    for(i = 1; i < n; i++) {
        if(arr[i] > maxSum) {
            maxSum = arr[i];
            *start = *finish = i;
        }
    }
    returnmaxSum;
}

// The main function that finds maximum
// sum rectangle in
// M[][]
voidfindMaxSum(intM[][COL])
{
    // Variables to store the final output
    intmaxSum = INT_MIN, finalLeft, finalRight, finalTop,
        finalBottom;

    intleft, right, i;
    inttemp[ROW], sum, start, finish;

    // Set the left column
    for(left = 0; left < COL; ++left) {
        // Initialize all elements of temp as 0
        memset(temp, 0, sizeof(temp));

        // Set the right column for the left column set by
        // outer loop
        for(right = left; right < COL; ++right) {
            // Calculate sum between current left and right
            // for every row 'i'
            for(i = 0; i < ROW; ++i)
                temp[i] += M[i][right];

            // Find the maximum sum subarray in temp[].
            // The kadane() function also sets values of
            // start and finish.  So 'sum' is sum of
            // rectangle between (start, left) and (finish,
            //  right) which is the maximum sum with
            //  boundary columns strictly as left and right.
            sum = kadane(temp, &start, &finish, ROW);

            // Compare sum with maximum sum so far. If sum
            // is more, then update maxSum and other output
            // values
            if(sum > maxSum) {
                maxSum = sum;
                finalLeft = left;
                finalRight = right;
                finalTop = start;
                finalBottom = finish;
            }
        }
    }

    // Print final values
    printf("(Top, Left) (%d, %d)\n", finalTop, finalLeft);
    printf("(Bottom, Right) (%d, %d)\n", finalBottom,
           finalRight);
    printf("Max sum is: %d\n", maxSum);
}

