    // Function to find maximum sum rectangular
    // submatrix
    privatestaticintmaxSumRectangle(int[][] mat)
    {
        intm = mat.length;
        intn = mat[0].length;
        intpreSum[][] = newint[m + 1][n];

        for(inti = 0; i < m; i++) {
            for(intj = 0; j < n; j++) {
                preSum[i + 1][j] = preSum[i][j] + mat[i][j];
            }
        }

        intmaxSum = -1;
        intminSum = Integer.MIN_VALUE;
        intnegRow = 0, negCol = 0;
        intrStart = 0, rEnd = 0, cStart = 0, cEnd = 0;
        for(introwStart = 0; rowStart < m; rowStart++) {
            for(introw = rowStart; row < m; row++) {
                intsum = 0;
                intcurColStart = 0;
                for(intcol = 0; col < n; col++) {
                    sum += preSum[row + 1][col]
                           - preSum[rowStart][col];
                    if(sum < 0) {
                        if(minSum < sum) {
                            minSum = sum;
                            negRow = row;
                            negCol = col;
                        }
                        sum = 0;
                        curColStart = col + 1;
                    }
                    elseif(maxSum < sum) {
                        maxSum = sum;
                        rStart = rowStart;
                        rEnd = row;
                        cStart = curColStart;
                        cEnd = col;
                    }
                }
            }
        }

