  TreeNode  left,  right;
  TreeNode(intdata)
  {
      this.data=data;
      left=null;
      right=null;
  }
}

classPair {
    TreeNode node; 
    intnum; 
    Pair(TreeNode _node, int_num) {
        num = _num;
        node = _node; 
    }
}
classSolution {
    publicstaticintwidthOfBinaryTree(TreeNode root) {
        if(root == null) return0;
        intans = 0;
        Queue<Pair> q = newLinkedList<>(); 
        q.offer(newPair(root, 0)); 
        while(!q.isEmpty()){
            intsize = q.size();
            intmmin = q.peek().num;    //to make the id starting from zero
            intfirst = 0,last = 0;
            for(inti=0; i<size; i++){
                intcur_id = q.peek().num-mmin;
                TreeNode node = q.peek().node;
                q.poll();
                if(i==0) first = cur_id;
                if(i==size-1) last = cur_id;
                if(node.left != null)
                    q.offer(newPair(node.left, cur_id*2+1));
                if(node.right != null) 
                    q.offer(newPair(node.right, cur_id*2+2));
            }
            ans = Math.max(ans, last-first+1);
        }
        returnans;
    }


