// C# Code for the above approach
usingSystem;

/* A binary tree node has data,
a pointer to left child
and a pointer to right child */
publicclassNode {
  publicintdata;
  publicNode left;
  publicNode right;
}

publicclassProgram {
  // Function to return a new Node
  staticNode newNode(intdata)
  {
    Node node = newNode();
    node.data = data;
    node.left = null;
    node.right = null;

    returnnode;
  }

  // Function to convert bst to
  // a doubly linked list
  staticvoidbstTodll(Node root, refNode head)
  {
    // if root is NUL
    if(root == null)
      return;

    // Convert right subtree recursively
    bstTodll(root.right, refhead);

    // Update root
    root.right = head;

    // if head is not NULL
    if(head != null)

      // Update left of the head
      head.left = root;

    // Update head
    head = root;

    // Convert left subtree recursively
    bstTodll(root.left, refhead);
  }

  // Function to merge two sorted linked list
  staticNode mergeLinkedList(Node head1, Node head2)
  {
    /*Create head and tail for result list*/
    Node head = null, tail = null;

    while(head1 != null&& head2 != null) {
      if(head1.data < head2.data) {
        if(head == null)
          head = head1;
        else{
          tail.right = head1;
          head1.left = tail;
        }

        tail = head1;
        head1 = head1.right;
      }
      else{
        if(head == null)
          head = head2;
        else{
          tail.right = head2;
          head2.left = tail;
        }

        tail = head2;
        head2 = head2.right;
      }
    }

    while(head1 != null) {
      tail.right = head1;
      head1.left = tail;
      tail = head1;
      head1 = head1.right;
    }

    while(head2 != null) {
      tail.right = head2;
      head2.left = tail;
      tail = head2;
      head2 = head2.right;
    }

    // Return the created DLL
    returnhead;
  }

  // function to convert list to bst
  staticNode sortedListToBST(refNode head, intn)
  {
    // if no element is left or head is null
    if(n <= 0 || head == null)
      returnnull;
    // Create left part from the list recursively
    Node left = sortedListToBST(refhead, n / 2);

    Node root = head;
    root.left = left;
    head = head.right;

    // Create left part from the list recursively
    root.right
      = sortedListToBST(refhead, n - (n / 2) - 1);

    // Return the root of BST
    returnroot;
  }

  // This function merges two balanced BSTs

  staticNode mergeTrees(Node root1, Node root2, intm,
                         intn)
  {
    // Convert BSTs into sorted Doubly Linked Lists
    Node head1 = null;
    bstTodll(root1, refhead1);
    head1.left = null;

    Node head2 = null;
    bstTodll(root2, refhead2);
    head2.left = null;

    // Merge the two sorted lists into one
    Node head = mergeLinkedList(head1, head2);

    // Construct a tree from the merged lists
    returnsortedListToBST(refhead, m + n);
  }

  staticvoidprintInorder(Node node)
  {
    // if current node is NULL
    if(node == null)
      return;

    printInorder(node.left);

    // Print node of current data
    Console.Write(node.data + " ");
    printInorder(node.right);
