voidbstTodll(Node* root, Node*& head)
{
    // if root is NULL
    if(!root)
        return;

    // Convert right subtree recursively
    bstTodll(root->right, head);

    // Update root
    root->right = head;

    // if head is not NULL
    if(head) {

        // Update left of the head
        head->left = root;
    }

    // Update head
    head = root;

    // Convert left subtree recursively
    bstTodll(root->left, head);
}

// Function to merge two sorted linked list
Node* mergeLinkedList(Node* head1, Node* head2)
{

    /*Create head and tail for result list*/
    Node* head = NULL;
    Node* tail = NULL;

    while(head1 && head2) {

        if(head1->data < head2->data) {

            if(!head)
                head = head1;
            else{

                tail->right = head1;
                head1->left = tail;
            }

            tail = head1;
            head1 = head1->right;
        }

        else{

            if(!head)
                head = head2;
            else{
                tail->right = head2;
                head2->left = tail;
            }

            tail = head2;
            head2 = head2->right;
        }
    }

    while(head1) {
        tail->right = head1;
        head1->left = tail;
        tail = head1;
        head1 = head1->right;
    }

    while(head2) {
        tail->right = head2;
        head2->left = tail;
        tail = head2;
        head2 = head2->right;
    }

    // Return the created DLL
    returnhead;
}

// function to convert list to bst
Node* sortedListToBST(Node*& head, intn)
{
    // if no element is left or head is null
    if(n <= 0 || !head)
        returnNULL;

    // Create left part from the list recursively
    Node* left = sortedListToBST(head, n / 2);

    Node* root = head;
    root->left = left;
    head = head->right;

    // Create left part from the list recursively
    root->right = sortedListToBST(head, n - (n / 2) - 1);

    // Return the root of BST
    returnroot;
}

