    publicBinaryTree() { this.root = null; }

    publicvoidinsert(intdata)
    {
        this.root = insertRec(this.root, data);
    }

    privateNode insertRec(Node root, intdata)
    {
        if(root == null) {
            root = newNode(data);
            returnroot;
        }

        if(data < root.data) {
            root.left = insertRec(root.left, data);
        }
        elseif(data > root.data) {
            root.right = insertRec(root.right, data);
        }

        returnroot;
    }

    /* convert sorted Double linked list */
    publicvoidconvertIntoSortedDLL(Node root,
                                     refNode head)
    {
        // base case
        if(root == null) {
            return;
        }

        convertIntoSortedDLL(root.right, refhead);
        root.right = head;

        if(head != null) {
            head.left = root;
        }

        head = root;

        convertIntoSortedDLL(root.left, refhead);
    }

    /* Merge sorted Double linked list */
    publicNode mergeLinkedList(Node head1, Node head2)
    {
        Node dummy = newNode(0);

        /* tail points to the last result node */
        Node tail = dummy;

        /* so tail->next is the place to
      add new nodes to the result. */
        while(true) {
            if(head1 == null) {
                /* if either list runs out, use the
              other list */
                tail.right = head2;
                break;
            }

            if(head2 == null) {
                tail.right = head1;
                break;
            }

            if(head1.data <= head2.data) {
                tail.right = head1;
                head1.left = tail;
                head1 = head1.right;
            }
            else{
                tail.right = head2;
                head2.left = tail;
