/* Utility function to create a new Binary Tree Node */
Node* newNode(intdata)
{
    Node* temp = newNode;
    temp->val = data;
    temp->left = nullptr;
    temp->right = nullptr;
    returntemp;
}

/* UTILITY FUNCTIONS */
/* MoveNode() function takes the
node from the front of the source,
and move it to the front of the dest.
It is an error to call this with the
source list empty.
 
Before calling MoveNode():
source == {1, 2, 3}
dest == {1, 2, 3}
 
After calling MoveNode():
source == {2, 3}
dest == {1, 1, 2, 3} */
voidMoveNode(Node** destRef, Node** sourceRef)
{
    /* the front source node */
    Node* newNode = *sourceRef;
    assert(newNode != NULL);
 
    /* Advance the source pointer */
    *sourceRef = newNode->right;
 
    /* Link the old dest of the new node */
    newNode->right = *destRef;
 
    /* Move dest to point to the new node */
    *destRef = newNode;
}


/* Merge sorted Double linked list */
Node* mergeLinkedList(Node* a, Node* b)
{
      Node dummy;
 
    /* tail points to the last result node */
    Node* tail = &dummy
 
    /* so tail->next is the place to
    add new nodes to the result. */
    dummy.right = NULL;
    while(1) {
        if(a == NULL) {
            /* if either list runs out, use the
            other list */
            tail->right = b;
            break;
        }
        elseif(b == NULL) {
            tail->right = a;
            break;
        }
        if(a->val <= b->val)
            MoveNode(&(tail->right), &a);
        else
            MoveNode(&(tail->right), &b);
 
        tail = tail->right;
    }
    return(dummy.right);
}

/* convert sorted Double linked list */
voidconvertIntoSortedDLL(Node* root, Node*& head)
{
      //base case
    if(root == NULL)
        return;
  
    convertIntoSortedDLL(root->right, head);
    root->right = head;
  
    if(head != NULL)
        head->left = root;
  
    head = root;
  
    convertIntoSortedDLL(root->left, head);
}

