    publicvoidinsert(intdata) {
        root = insertRec(root, data);
    }

    publicNode insertRec(Node root, intdata) {
        if(root == null) {
            root = newNode(data);
            returnroot;
        }

        if(data < root.data) {
            root.left = insertRec(root.left, data);
        } elseif(data > root.data) {
            root.right = insertRec(root.right, data);
        }

        returnroot;
    }

    /* convert sorted Double linked list */
    publicvoidconvertIntoSortedDLL(Node root, Node[] head) {
        if(root == null) {
            return;
        }

        convertIntoSortedDLL(root.right, head);
        root.right = head[0];

        if(head[0] != null) {
            head[0].left = root;
        }

        head[0] = root;

        convertIntoSortedDLL(root.left, head);
    }

    /* Merge sorted Double linked list */
    publicNode mergeLinkedList(Node head1, Node head2) {
        Node dummy = newNode(0);
        
        /* tail points to the last result node */
        Node tail = dummy;

        /* so tail->next is the place to
      add new nodes to the result. */
        while(true) {
