{
    intk = 3;
    intarr[] = { 2, 6, 3, 12, 56, 8 };
    intn = sizeof(arr) / sizeof(arr[0]);

    // Function call
    sortK(arr, n, k);

    printArray(arr, n);

    return0;
}

