  for(intk = 0; k < n; k++) {
    for(inti = 0; i < n; i++) {
      for(intj = 0; j < n; j++) {
        // Relax the edge (i, j) using the vertex k as the intermediate vertex
        dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
