    string txt = "geeksforgeeks.org";
    SuffixTrie S(txt);

    cout << "Search for 'ee'"<< endl;
    S.search("ee");

    cout << "\nSearch for 'geek'"<< endl;
    S.search("geek");

    cout << "\nSearch for 'quiz'"<< endl;
    S.search("quiz");

    cout << "\nSearch for 'forgeeks'"<< endl;
    S.search("forgeeks");

