// C# program to implement persistent
// segment tree.
usingSystem;

classnode
{
    
    // Stores sum of the elements in node
    publicintval;
    
    // Reference to left and right children
    publicnode left, right;
    
    // Required constructors..
    publicnode()
    {}

    // Node constructor for l,r,v
    publicnode(node l, node r, intv)
    {
        left = l;
        right = r;
        val = v;
    }
}

classGFG{
    
// Declaring maximum number
staticintMAXN = 100;

// Making Node for tree
// Input array
staticint[] arr = newint[MAXN];

// Root pointers for all versions
staticnode[] version = newnode[MAXN];

// Constructs Version-0
// Time Complexity : O(nlogn)
staticvoidbuild(node n, intlow, inthigh)
{
    if(low == high)
    {
        n.val = arr[low];
        return;
    }

    intmid = (low + high) / 2;
    n.left = newnode(null, null, 0);
    n.right = newnode(null, null, 0);
    build(n.left, low, mid);
    build(n.right, mid + 1, high);
    n.val = n.left.val + n.right.val;
}

/* Upgrades to new Version
 * @param prev : points to node of previous version
 * @param cur  : points to node of current version
 * Time Complexity : O(logn)
 * Space Complexity : O(logn)  */
staticvoidupgrade(node prev, node cur, intlow,
                      inthigh, intidx, intvalue)
{
    if(idx > high || idx < low || low > high)
        return;
        
    if(low == high)
    {
        
        // Modification in new version
        cur.val = value;
        return;
    }

    intmid = (low + high) / 2;
    
    if(idx <= mid)
    {
        
        // Link to right child of previous version
        cur.right = prev.right;
        
        // Create new node in current version
        cur.left = newnode(null, null, 0);
        upgrade(prev.left, cur.left, low,
                mid, idx, value);
    }
    else
    {
        
        // Link to left child of previous version
        cur.left = prev.left;
        
        // Create new node for current version
        cur.right = newnode(null, null, 0);
        upgrade(prev.right, cur.right, 
                mid + 1, high, idx, value);
    }

    // Calculating data for current version
    // by combining previous version and current
    // modification
    cur.val = cur.left.val + cur.right.val;
}

staticintquery(node n, intlow, inthigh,
                         intl, intr)
{
    if(l > high || r < low || low > high)
        return0;
        
    if(l <= low && high <= r)
        returnn.val;
        
    intmid = (low + high) / 2;
    intp1 = query(n.left, low, mid, l, r);
    intp2 = query(n.right, mid + 1, high, l, r);
    returnp1 + p2;
}

// Driver code
publicstaticvoidMain(String[] args)
{
    int[] A = { 1, 2, 3, 4, 5 };
    intn = A.Length;
    
    for(inti = 0; i < n; i++)
        arr[i] = A[i];
    
    // Creating Version-0
    node root = newnode(null, null, 0);
    build(root, 0, n - 1);
    
    // Storing root node for version-0
    version[0] = root;
    
    // Upgrading to version-1
    version[1] = newnode(null, null, 0);
    upgrade(version[0], version[1], 0, 
            n - 1, 4, 1);
    
    // Upgrading to version-2
    version[2] = newnode(null, null, 0);
    upgrade(version[1], version[2], 0, 
