                                            intdir,
                                            List<int> res)
    {
        if(isBlocked(matrix, i, j))
            return;

        boolallBlocked = true;

        for(intk = -1; k <= 1; k += 2) {
            allBlocked = allBlocked
                         && isBlocked(matrix, k + i, j)
                         && isBlocked(matrix, i, j + k);
        }
        res.Add(matrix[i, j]);
        matrix[i, j] = -1;

        if(allBlocked) {
            return;
