    {
        this.data = data;
        left = right = null;
    }
}

classBinaryTree
{
    // Function to perform iterative DFS traversal and find all
    // nodes at distance K
    publicstaticList<int> Kdistance(Node root, intk)
    {
        List<int> result = newList<int>();
        Stack<Tuple<Node, int>> s = newStack<Tuple<Node, int>>();
        s.Push(newTuple<Node, int>(root, 0));

        while(s.Count > 0)
        {
            Tuple<Node, int> current = s.Pop();
            Node curr = current.Item1;
            intlevel = current.Item2;

            if(curr == null)
            {
                continue;
            }

            // If the current node is at distance K from the root, add its data to the result
            if(level == k)
            {
                result.Add(curr.data);
            }

            // Push the right child onto the stack with its level incremented by 1
            s.Push(newTuple<Node, int>(curr.right, level + 1));

            // Push the left child onto the stack with its level incremented by 1
            s.Push(newTuple<Node, int>(curr.left, level + 1));
        }

        returnresult;
    }

