            // if head is null, head = new_Node
            if(_head == null)
            {
                _head = new_Node;
                return;
            }

            /* link the old list of the new node */
            new_Node.Next = _head;

            /* change prev of head node to new node */
            _head.Prev = new_Node;

            /* since we are adding at the
            beginning, prev is always NULL */

            /* move the head to point to the new node */
            _head = new_Node;
        }

        /* Driver code */
    }
