    mt19937 generator(rand_dev()); 
 
    // Random number generated will be in the range [0,n-1] 
    uniform_int_distribution<int> distribution(0, n-1); 
 
    if(n==0) 
        return0; 
 
    intk = 10*log2(n); // Taking c as 10 
 
    // A set stores unique elements in sorted order 
    set<int> s; 
