// Importing the System namespace which contains classes used in the program
usingSystem;

// Defining the Node class with an integer array to hold the point and references to left and right nodes
classNode {
  publicint[] point;
  publicNode left;
  publicNode right;

  // Defining a constructor to initialize the Node object
  publicNode(int[] point) {
      this.point = point;
      left = null;
      right = null;
  }

}

// Defining the KdTree class to represent a K-d tree with a specified value of k
classKdTree {
  privateintk;

  // Defining a constructor to initialize the KdTree object
  publicKdTree(intk) {
      this.k = k;
  }

  // Defining a method to create a new Node object
  publicNode newNode(int[] point) {
      returnnewNode(point);
  }

  // Defining a recursive method to insert a point into the K-d tree
  privateNode insertRec(Node root, int[] point, intdepth) {
      if(root == null) {
          returnnewNode(point);
      }

      intcd = depth % k;

      if(point[cd] < root.point[cd]) {
          root.left = insertRec(root.left, point, depth + 1);
      } 
      else{
          root.right = insertRec(root.right, point, depth + 1);
      }

      returnroot;
  }

  // Defining a method to insert a point into the K-d tree
  publicNode insert(Node root, int[] point) {
      returninsertRec(root, point, 0);
  }

  // Defining a method to check if two points are the same
  privateboolarePointsSame(int[] point1, int[] point2) {
      for(inti = 0; i < k; i++) {
          if(point1[i] != point2[i]) {
              returnfalse;
          }
      }

      returntrue;
  }

  // Defining a recursive method to search for a point in the K-d tree
  privateboolsearchRec(Node root, int[] point, intdepth) {
      if(root == null) {
          returnfalse;
      }

      if(arePointsSame(root.point, point)) {
          returntrue;
      }

      intcd = depth % k;

      if(point[cd] < root.point[cd]) {
          returnsearchRec(root.left, point, depth + 1);
      }

      returnsearchRec(root.right, point, depth + 1);
  }

  // Defining a method to search for a point in the K-d tree
  publicboolsearch(Node root, int[] point) {
      returnsearchRec(root, point, 0);
  }

}

