// A C++ program to demonstrate operations of KD tree
#include<bits/stdc++.h>
usingnamespacestd;

constintk = 2;

// A structure to represent node of kd tree
structNode
{
    intpoint[k]; // To store k dimensional point
    Node *left, *right;
};

// A method to create a node of K D tree
structNode* newNode(intarr[])
{
    structNode* temp = newNode;

    for(inti=0; i<k; i++)
       temp->point[i] = arr[i];

    temp->left = temp->right = NULL;
    returntemp;
}

// Inserts a new node and returns root of modified tree
// The parameter depth is used to decide axis of comparison
Node *insertRec(Node *root, intpoint[], unsigned depth)
{
    // Tree is empty?
    if(root == NULL)
       returnnewNode(point);

    // Calculate current dimension (cd) of comparison
    unsigned cd = depth % k;

    // Compare the new point with root on current dimension 'cd'
    // and decide the left or right subtree
    if(point[cd] < (root->point[cd]))
        root->left  = insertRec(root->left, point, depth + 1);
    else
        root->right = insertRec(root->right, point, depth + 1);

    returnroot;
}

// Function to insert a new point with given point in
// KD Tree and return new root. It mainly uses above recursive
// function "insertRec()"
Node* insert(Node *root, intpoint[])
{
    returninsertRec(root, point, 0);
}

// A utility method to determine if two Points are same
// in K Dimensional space
boolarePointsSame(intpoint1[], intpoint2[])
{
    // Compare individual pointinate values
    for(inti = 0; i < k; ++i)
        if(point1[i] != point2[i])
            returnfalse;

    returntrue;
}

// Searches a Point represented by "point[]" in the K D tree.
// The parameter depth is used to determine current axis.
boolsearchRec(Node* root, intpoint[], unsigned depth)
{
    // Base cases
    if(root == NULL)
        returnfalse;
    if(arePointsSame(root->point, point))
        returntrue;

    // Current dimension is computed using current depth and total
    // dimensions (k)
    unsigned cd = depth % k;

    // Compare point with root with respect to cd (Current dimension)
    if(point[cd] < root->point[cd])
        returnsearchRec(root->left, point, depth + 1);

