        Queue<qentry> q = newQueue<qentry>();
        qentry qe = newqentry();
        qe.v = 0;
        qe.dist = 0;

        // Mark the node 0 as visited and enqueue it.
        visited[0] = 1;
        q.Enqueue(qe);

        // Do a BFS starting from vertex at index 0
        while(q.Count != 0) {
