// A utility function to insert a new node at the beginning of linked list
functionpush(head_ref, new_data) {
  /* allocate node */
const new_node = newListNode(new_data);
/* link the old list off the new node */
new_node.next = head_ref;
/* move the head to point to the new node */
head_ref = new_node;
returnhead_ref;
}

// A utility function to swap two min heap nodes. This function
// is needed in minHeapify
functionswap(a, b) {
const temp = a;
a = b;
b = temp;
return[a, b];
}

// The standard minHeapify function.
functionmin_heapify(min_heap, idx) {
const left = 2 * idx + 1;
const right = 2 * idx + 2;
let smallest = idx;

if(
left < min_heap.count &&
min_heap.array[left][0].val < min_heap.array[smallest][0].val
) {
smallest = left;
}
if(
right < min_heap.count &&
min_heap.array[right][0].val < min_heap.array[smallest][0].val
) {
smallest = right;
}
if(smallest !== idx) {
[min_heap.array[smallest], min_heap.array[idx]] = swap(
min_heap.array[smallest],
min_heap.array[idx]
);
min_heapify(min_heap, smallest);
}
}

