/* A Backtracking program in 
C# to solve Sudoku problem */
usingSystem;

classGFG 
{

    publicstaticboolisSafe(int[, ] board,
                              introw, intcol,
                              intnum)
    {
        
        // Row has the unique (row-clash)
        for(intd = 0; d < board.GetLength(0); d++) 
        {
            
            // Check if the number
            // we are trying to
            // place is already present in
            // that row, return false;
            if(board[row, d] == num) 
            {
                returnfalse;
            }
        }

        // Column has the unique numbers (column-clash)
        for(intr = 0; r < board.GetLength(0); r++) 
        {
            
            // Check if the number 
            // we are trying to
            // place is already present in
            // that column, return false;
            if(board[r, col] == num) 
            {
                returnfalse;
            }
        }

        // corresponding square has
        // unique number (box-clash)
        intsqrt = (int)Math.Sqrt(board.GetLength(0));
        intboxRowStart = row - row % sqrt;
        intboxColStart = col - col % sqrt;

        for(intr = boxRowStart;
             r < boxRowStart + sqrt; r++) 
        {
            for(intd = boxColStart;
                 d < boxColStart + sqrt; d++) 
            {
                if(board[r, d] == num) 
                {
                    returnfalse;
                }
            }
        }

        // if there is no clash, it's safe
        returntrue;
    }

    publicstaticboolsolveSudoku(int[, ] board, 
                                           intn)
    {
        introw = -1;
        intcol = -1;
        boolisEmpty = true;
        for(inti = 0; i < n; i++) 
        {
            for(intj = 0; j < n; j++) 
            {
                if(board[i, j] == 0) 
                {
                    row = i;
                    col = j;

                    // We still have some remaining
                    // missing values in Sudoku
                    isEmpty = false;
                    break;
                }
            }
            if(!isEmpty) 
            {
                break;
            }
        }

        // no empty space left
        if(isEmpty) 
        {
            returntrue;
        }

        // else for each-row backtrack
        for(intnum = 1; num <= n; num++) 
        {
            if(isSafe(board, row, col, num)) 
            {
                board[row, col] = num;
                if(solveSudoku(board, n)) 
                {
                    
                    // Print(board, n);
                    returntrue;
                }
                else
                {
                    
                    // Replace it
                    board[row, col] = 0;
                }
            }
        }
        returnfalse;
    }

    publicstaticvoidprint(int[, ] board, intN)
    {
        
        // We got the answer, just print it
        for(intr = 0; r < N; r++) 
        {
            for(intd = 0; d < N; d++) 
            {
                Console.Write(board[r, d]);
                Console.Write(" ");
            }
            Console.Write("\n");

            if((r + 1) % (int)Math.Sqrt(N) == 0) 
            {
                Console.Write("");
            }
        }
    }

    // Driver Code
    publicstaticvoidMain(String[] args)
    {

        int[, ] board = newint[, ] {
            { 3, 0, 6, 5, 0, 8, 4, 0, 0 },
            { 5, 2, 0, 0, 0, 0, 0, 0, 0 },
            { 0, 8, 7, 0, 0, 0, 0, 3, 1 },
            { 0, 0, 3, 0, 1, 0, 0, 8, 0 },
            { 9, 0, 0, 8, 6, 3, 0, 0, 5 },
            { 0, 5, 0, 0, 9, 0, 6, 0, 0 },
            { 1, 3, 0, 0, 0, 0, 2, 5, 0 },
            { 0, 0, 0, 0, 0, 0, 0, 7, 4 },
            { 0, 0, 5, 2, 0, 6, 3, 0, 0 }
        };
        intN = board.GetLength(0);

        if(solveSudoku(board, N)) 
        {
            
            // print solution
            print(board, N); 
        }
        else{
            Console.Write("No solution");
        }
    }
}

