// A Backtracking program in
// C++ to solve Sudoku problem
#include <bits/stdc++.h>
usingnamespacestd;

// UNASSIGNED is used for empty
// cells in sudoku grid
#define UNASSIGNED 0

// N is used for the size of Sudoku grid.
// Size will be NxN
#define N 9

// This function finds an entry in grid
// that is still unassigned
boolFindUnassignedLocation(intgrid[N][N],
                            int& row, int& col);

// Checks whether it will be legal
// to assign num to the given row, col
boolisSafe(intgrid[N][N], introw,
            intcol, intnum);

/* Takes a partially filled-in grid and attempts 
to assign values to all unassigned locations in 
such a way to meet the requirements for
Sudoku solution (non-duplication across rows,
columns, and boxes) */
boolSolveSudoku(intgrid[N][N])
{
    introw, col;

    // If there is no unassigned location,
    // we are done
    if(!FindUnassignedLocation(grid, row, col))
        // success!
        returntrue;

    // Consider digits 1 to 9
    for(intnum = 1; num <= 9; num++) 
    {
        
        // Check if looks promising
        if(isSafe(grid, row, col, num)) 
        {
            
            // Make tentative assignment
            grid[row][col] = num;

            // Return, if success
            if(SolveSudoku(grid))
                returntrue;

            // Failure, unmake & try again
            grid[row][col] = UNASSIGNED;
        }
    }
   
    // This triggers backtracking
    returnfalse;
}

/* Searches the grid to find an entry that is 
still unassigned. If found, the reference 
parameters row, col will be set the location 
that is unassigned, and true is returned. 
If no unassigned entries remain, false is returned. */
boolFindUnassignedLocation(intgrid[N][N],
                            int& row, int& col)
{
    for(row = 0; row < N; row++)
        for(col = 0; col < N; col++)
            if(grid[row][col] == UNASSIGNED)
                returntrue;
    returnfalse;
}

/* Returns a boolean which indicates whether 
an assigned entry in the specified row matches
the given number. */
boolUsedInRow(intgrid[N][N], introw, intnum)
{
    for(intcol = 0; col < N; col++)
        if(grid[row][col] == num)
            returntrue;
    returnfalse;
}

/* Returns a boolean which indicates whether 
an assigned entry in the specified column
matches the given number. */
boolUsedInCol(intgrid[N][N], intcol, intnum)
{
    for(introw = 0; row < N; row++)
        if(grid[row][col] == num)
            returntrue;
    returnfalse;
}

/* Returns a boolean which indicates whether 
an assigned entry within the specified 3x3 box 
matches the given number. */
boolUsedInBox(intgrid[N][N], intboxStartRow,
               intboxStartCol, intnum)
{
    for(introw = 0; row < 3; row++)
        for(intcol = 0; col < 3; col++)
            if(grid[row + boxStartRow]
                    [col + boxStartCol] ==
                                       num)
                returntrue;
    returnfalse;
}

/* Returns a boolean which indicates whether 
it will be legal to assign num to the given 
row, col location. */
boolisSafe(intgrid[N][N], introw,
            intcol, intnum)
{
    /* Check if 'num' is not already placed in 
    current row, current column 
    and current 3x3 box */
    return!UsedInRow(grid, row, num)
           && !UsedInCol(grid, col, num)
           && !UsedInBox(grid, row - row % 3,
                         col - col % 3, num)
           && grid[row][col] == UNASSIGNED;
}

/* A utility function to print grid */
voidprintGrid(intgrid[N][N])
{
    for(introw = 0; row < N; row++) 
    {
