/* A Backtracking program in 
Java to solve Sudoku problem */
classGFG 
{
    publicstaticbooleanisSafe(int[][] board,
                                 introw, intcol,
                                 intnum)
    {
        // Row has the unique (row-clash)
        for(intd = 0; d < board.length; d++) 
        {
            
            // Check if the number we are trying to
            // place is already present in
            // that row, return false;
            if(board[row][d] == num) {
                returnfalse;
            }
        }

        // Column has the unique numbers (column-clash)
        for(intr = 0; r < board.length; r++) 
        {
            
            // Check if the number 
            // we are trying to
            // place is already present in
            // that column, return false;
            if(board[r][col] == num) 
            {
                returnfalse;
            }
        }

        // Corresponding square has
        // unique number (box-clash)
        intsqrt = (int)Math.sqrt(board.length);
        intboxRowStart = row - row % sqrt;
        intboxColStart = col - col % sqrt;

        for(intr = boxRowStart;
             r < boxRowStart + sqrt; r++) 
        {
            for(intd = boxColStart;
                 d < boxColStart + sqrt; d++) 
            {
                if(board[r][d] == num) 
                {
                    returnfalse;
                }
            }
        }

        // if there is no clash, it's safe
        returntrue;
    }

    publicstaticbooleansolveSudoku(
        int[][] board, intn)
    {
        introw = -1;
        intcol = -1;
        booleanisEmpty = true;
        for(inti = 0; i < n; i++) 
        {
            for(intj = 0; j < n; j++) 
            {
                if(board[i][j] == 0) 
                {
                    row = i;
                    col = j;

                    // We still have some remaining
                    // missing values in Sudoku
                    isEmpty = false;
                    break;
                }
            }
            if(!isEmpty) {
                break;
            }
        }

        // No empty space left
        if(isEmpty) 
        {
            returntrue;
        }

        // Else for each-row backtrack
        for(intnum = 1; num <= n; num++) 
        {
            if(isSafe(board, row, col, num)) 
            {
                board[row][col] = num;
                if(solveSudoku(board, n)) 
