#include <bits/stdc++.h>
usingnamespacestd;

#define N 9

// Bitmasks for each row/column/box
introw[N], col[N], box[N];
boolseted = false;

// Utility function to find the box index
// of an element at position [i][j] in the grid
intgetBox(inti, intj) { returni / 3 * 3 + j / 3; }

// Utility function to check if a number
// is present in the corresponding row/column/box
boolisSafe(inti, intj, intnumber)
{
    return!((row[i] >> number) & 1)
           && !((col[j] >> number) & 1)
           && !((box[getBox(i, j)] >> number) & 1);
}

// Utility function to set the initial values of a Sudoku
// board (map the values in the bitmasks)
voidsetInitialValues(intgrid[N][N])
{
    for(inti = 0; i < N; i++)
        for(intj = 0; j < N; j++)
            row[i] |= 1 << grid[i][j],
                col[j] |= 1 << grid[i][j],
                box[getBox(i, j)] |= 1 << grid[i][j];
}

/* Takes a partially filled-in grid and attempts
to assign values to all unassigned locations in
such a way to meet the requirements for
Sudoku solution (non-duplication across rows,
columns, and boxes) */
boolSolveSudoku(intgrid[N][N], inti, intj)
{
    // Set the initial values
    if(!seted)
        seted = true, setInitialValues(grid);

    if(i == N - 1 && j == N)
        returntrue;
    if(j == N)
        j = 0, i++;

    if(grid[i][j])
        returnSolveSudoku(grid, i, j + 1);

    for(intnr = 1; nr <= N; nr++) {
        if(isSafe(i, j, nr)) {
            /*  Assign nr in the
                current (i, j)
                position and
                add nr to each bitmask
            */
            grid[i][j] = nr;
            row[i] |= 1 << nr;
            col[j] |= 1 << nr;
            box[getBox(i, j)] |= 1 << nr;

            if(SolveSudoku(grid, i, j + 1))
                returntrue;

            // Remove nr from each bitmask
            // and search for another possibility
            row[i] &= ~(1 << nr);
            col[j] &= ~(1 << nr);
            box[getBox(i, j)] &= ~(1 << nr);
        }

        grid[i][j] = 0;
    }

    returnfalse;
}

// Utility function to print the solved grid
voidprint(intgrid[N][N])
{
    for(inti = 0; i < N; i++, cout << '\n')
        for(intj = 0; j < N; j++)
            cout << grid[i][j] << ' ';
}

// Driver Code
