inttraverseEdge(char*str, intidx, intstart, intend)
{
    intk = 0;
    //Traverse the edge with character by character matching
    for(k=start; k<=end && str[idx] != '&#092;&#048;'; k++, idx++)
    {
        if(text[k] != str[idx])
            return-1;  // mo match
    }
    if(str[idx] == '&#092;&#048;')
        return1;  // match
    return0;  // more characters yet to match
}

intdoTraversalToCountLeaf(Node *n)
{
    if(n == NULL)
        return0;
    if(n->suffixIndex > -1)
    {
        printf("\nFound at position: %d", n->suffixIndex);
        return1;
    }
    intcount = 0;
    inti = 0;
    for(i = 0; i < MAX_CHAR; i++)
    {
        if(n->children[i] != NULL)
        {
            count += doTraversalToCountLeaf(n->children[i]);
        }
    }
    returncount;
}

intcountLeaf(Node *n)
{
    if(n == NULL)
        return0;
    returndoTraversalToCountLeaf(n);
}

intdoTraversal(Node *n, char* str, intidx)
{
    if(n == NULL)
    {
        return-1; // no match
    }
    intres = -1;
    //If node n is not root node, then traverse edge
    //from node n's parent to node n.
    if(n->start != -1)
    {
        res = traverseEdge(str, idx, n->start, *(n->end));
        if(res == -1)  //no match
            return-1;
        if(res == 1) //match
        {
            if(n->suffixIndex > -1)
                printf("\nsubstring count: 1 and position: %d",
                               n->suffixIndex);
            else
                printf("\nsubstring count: %d", countLeaf(n));
            return1;
        }
    }
    //Get the character index to search
    idx = idx + edgeLength(n);
    //If there is an edge from node n going out
    //with current character str[idx], traverse that edge
    if(n->children[str[idx]] != NULL)
        returndoTraversal(n->children[str[idx]], str, idx);
    else
        return-1;  // no match
}

voidcheckForSubString(char* str)
{
    intres = doTraversal(root, str, 0);
    if(res == 1)
        printf("\nPattern <%s> is a Substring\n", str);
    else
        printf("\nPattern <%s> is NOT a Substring\n", str);
}
 
