        publicNode(chardata) 
        { 
            this.data = data; 
            this.isEndOfString = false; 
            this.left = this.eq = this.right = null; 
        } 
    } 
 
    privateNode root; 
 
    publicTernarySearchTree() { this.root = null; } 
 
    publicvoidInsert(stringword) 
    { 
        if(string.IsNullOrEmpty(word)) 
            return; 
 
        this.root = InsertHelper(this.root, word, 0); 
    } 
 
    privateNode InsertHelper(Node node, stringword, 
                              intindex) 
    { 
        if(node == null) { 
            node = newNode(word[index]); 
        } 
 
        if(word[index] < node.data) { 
            node.left 
                = InsertHelper(node.left, word, index); 
        } 
        elseif(word[index] > node.data) { 
            node.right 
                = InsertHelper(node.right, word, index); 
        } 
        else{ 
            if(index < word.Length - 1) { 
                node.eq = InsertHelper(node.eq, word, 
                                       index + 1); 
            } 
            else{ 
                node.isEndOfString = true; 
            } 
        } 
 
        returnnode; 
    } 
 
    publicboolSearch(stringword) 
    { 
        if(string.IsNullOrEmpty(word)) 
            returnfalse; 
 
        returnSearchHelper(this.root, word, 0); 
    } 
 
    privateboolSearchHelper(Node node, stringword, 
                              intindex) 
    { 
        if(node == null) 
            returnfalse; 
 
        if(word[index] < node.data) { 
            returnSearchHelper(node.left, word, index); 
        } 
        elseif(word[index] > node.data) { 
            returnSearchHelper(node.right, word, index); 
        } 
        else{ 
            if(index == word.Length - 1) { 
                returnnode.isEndOfString; 
            } 
            else{ 
                returnSearchHelper(node.eq, word, 
                                    index + 1); 
            } 
        } 
    } 
 
    publicvoidTraverse() 
    { 
        TraverseHelper(this.root, ""); 
    } 
 
    privatevoidTraverseHelper(Node node, stringbuffer) 
    { 
        if(node == null) 
            return; 
 
        TraverseHelper(node.left, buffer); 
 
        buffer += node.data; 
 
        if(node.isEndOfString) { 
            Console.WriteLine(buffer); 
        } 
 
        TraverseHelper( 
            node.eq, buffer.Substring(0, buffer.Length - 1) 
                         + node.data); 
 
        TraverseHelper( 
            node.right, 
            buffer.Substring(0, buffer.Length - 1)); 
    } 
} 
 
