staticintfactorial(intn)
{
    intres = 1;

    // Calculate value of 
    // [1*(2)*---*(n-k+1)] / 
    // [k*(k-1)*---*1]
    for(inti = 1; i <= n; ++i)
    {
        res *= i;
    }

    returnres;
}

staticintbinomialCoeff(intn,
                         intk)
{
    intres = 1;

    // Since C(n, k) = C(n, n-k)
    if(k > n - k)
        k = n - k;

    // Calculate value of 
    // [n*(n-1)*---*(n-k+1)] / 
    // [k*(k-1)*---*1]
    for(inti = 0; i < k; ++i)
    {
        res *= (n - i);
        res /= (i + 1);
    }

    returnres;
}

