// C# program to solve Traveling Salesman Problem
// using Branch and Bound.
usingSystem;

publicclassGFG {

  staticintN = 4;

  // final_path[] stores the final solution ie, the
  // path of the salesman.
  staticint[] final_path = newint[N + 1];

  // visited[] keeps track of the already visited nodes
  // in a particular path
  staticbool[] visited = newbool[N];

  // Stores the final minimum weight of shortest tour.
  staticintfinal_res = Int32.MaxValue;

  // Function to copy temporary solution to
  // the final solution
  staticvoidcopyToFinal(int[] curr_path)
  {
    for(inti = 0; i < N; i++)
      final_path[i] = curr_path[i];
    final_path[N] = curr_path[0];
  }

  // Function to find the minimum edge cost
  // having an end at the vertex i
  staticintfirstMin(int[, ] adj, inti)
  {
    intmin = Int32.MaxValue;
    for(intk = 0; k < N; k++)
      if(adj[i, k] < min && i != k)
        min = adj[i, k];
    returnmin;
  }

  // function to find the second minimum edge cost
  // having an end at the vertex i
  staticintsecondMin(int[, ] adj, inti)
  {
    intfirst = Int32.MaxValue, second = Int32.MaxValue;
    for(intj = 0; j < N; j++) {
      if(i == j)
        continue;

      if(adj[i, j] <= first) {
        second = first;
        first = adj[i, j];
      }
      elseif(adj[i, j] <= second
               && adj[i, j] != first)
        second = adj[i, j];
    }
    returnsecond;
  }

