    pNode = (structTrieNode *)malloc(sizeof(structTrieNode));

    if(pNode)
    {
        inti;

        pNode->isEndOfWord = false;

        for(i = 0; i < ALPHABET_SIZE; i++)
            pNode->children[i] = NULL;
    }

    returnpNode;
}

