structQuery
{
    intx1, y1; // x and y co-ordinates of bottom left
    intx2, y2; // x and y co-ordinates of top right
};

// A function to update the 2D BIT
voidupdateBIT(intBIT[][N+1], intx, inty, intval)
{
    for(; x <= N; x += (x & -x))
    {
        // This loop update all the 1D BIT inside the
        // array of 1D BIT = BIT[x]
        for(intyy=y; yy <= N; yy += (yy & -yy))
            BIT[x][yy] += val;
    }
    return;
}

// A function to get sum from (0, 0) to (x, y)
intgetSum(intBIT[][N+1], intx, inty)
{
    intsum = 0;

    for(; x > 0; x -= x&-x)
    {
        // This loop sum through all the 1D BIT
        // inside the array of 1D BIT = BIT[x]
        for(intyy=y; yy > 0; yy -= yy&-yy)
        {
            sum += BIT[x][yy];
        }
    }
    returnsum;
}

// A function to create an auxiliary matrix
// from the given input matrix
voidconstructAux(intmat[][N], intaux[][N+1])
{
    // Initialise Auxiliary array to 0
    for(inti=0; i<=N; i++)
        for(intj=0; j<=N; j++)
            aux[i][j] = 0;

    // Construct the Auxiliary Matrix
    for(intj=1; j<=N; j++)
        for(inti=1; i<=N; i++)
            aux[i][j] = mat[N-j][i-1];

    return;
}

// A function to construct a 2D BIT
voidconstruct2DBIT(intmat[][N], intBIT[][N+1])
{
    // Create an auxiliary matrix
    intaux[N+1][N+1];
    constructAux(mat, aux);

    // Initialise the BIT to 0
    for(inti=1; i<=N; i++)
        for(intj=1; j<=N; j++)
            BIT[i][j] = 0;

    for(intj=1; j<=N; j++)
    {
        for(inti=1; i<=N; i++)
        {
            // Creating a 2D-BIT using update function
            // everytime we/ encounter a value in the
            // input 2D-array
            intv1 = getSum(BIT, i, j);
            intv2 = getSum(BIT, i, j-1);
            intv3 = getSum(BIT, i-1, j-1);
            intv4 = getSum(BIT, i-1, j);

            // Assigning a value to a particular element
            // of 2D BIT
            updateBIT(BIT, i, j, aux[i][j]-(v1-v2-v4+v3));
        }
    }

    return;
}

// A function to answer the queries
voidanswerQueries(Query q[], intm, intBIT[][N+1])
{
    for(inti=0; i<m; i++)
    {
        intx1 = q[i].x1 + 1;
        inty1 = q[i].y1 + 1;
        intx2 = q[i].x2 + 1;
        inty2 = q[i].y2 + 1;

        intans = getSum(BIT, x2, y2)-getSum(BIT, x2, y1-1)-
                  getSum(BIT, x1-1, y2)+getSum(BIT, x1-1, y1-1);

        printf("Query(%d, %d, %d, %d) = %d\n",
                q[i].x1, q[i].y1, q[i].x2, q[i].y2, ans);
    }
    return;
}

// Driver program
intmain()
{
    intmat[N][N] = {{1, 2, 3, 4},
                    {5, 3, 8, 1},
                    {4, 6, 7, 5},
                    {2, 4, 8, 9}};

    // Create a 2D Binary Indexed Tree
    intBIT[N+1][N+1];
    construct2DBIT(mat, BIT);

    /* Queries of the form - x1, y1, x2, y2
       For example the query- {1, 1, 3, 2} means the sub-matrix-
    y
    /\
 3  |       1 2 3 4      Sub-matrix
 2  |       5 3 8 1      {1,1,3,2}      --->     3 8 1
 1  |       4 6 7 5                                 6 7 5
 0  |       2 4 8 9
    |
  --|------ 0 1 2 3 ----> x
    |

    Hence sum of the sub-matrix = 3+8+1+6+7+5 = 30

    */

    Query q[] = {{1, 1, 3, 2}, {2, 3, 3, 3}, {1, 1, 1, 1}};
    intm = sizeof(q)/sizeof(q[0]);

    answerQueries(q, m, BIT);

    return(0);
}

