// C++ program for printing vertical order of a given binary
// tree
#include <bits/stdc++.h>
usingnamespacestd;

// Structure for a binary tree node
structNode {
    intkey;
    Node *left, *right;
};

// A utility function to create a new node
structNode* newNode(intkey)
{
    structNode* node = newNode;
    node->key = key;
    node->left = node->right = NULL;
    returnnode;
}

// Utility function to store vertical order in map 'm'
// 'hd' is horizontal distance of current node from root.
// 'hd' is initially passed as 0
voidgetVerticalOrder(Node* root, inthd,
                      map<int, vector<int> >& m)
{
    // Base case
    if(root == NULL)
        return;

    // Store current node in map 'm'
    m[hd].push_back(root->key);

    // Store nodes in left subtree
    getVerticalOrder(root->left, hd - 1, m);

    // Store nodes in right subtree
    getVerticalOrder(root->right, hd + 1, m);
}

// The main function to print vertical order of a binary
// tree with the given root
voidprintVerticalOrder(Node* root)
{
    // Create a map and store vertical order in map using
    // function getVerticalOrder()
    map<int, vector<int> > m;
    inthd = 0;
    getVerticalOrder(root, hd, m);

    // Traverse the map and print nodes at every horizontal
    // distance (hd)
    map<int, vector<int> >::iterator it;
    for(it = m.begin(); it != m.end(); it++) {
        for(inti = 0; i < it->second.size(); ++i)
            cout << it->second[i] << " ";
        cout << endl;
    }
}

// Driver code
intmain()
{
    Node* root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(4);
    root->left->right = newNode(5);
    root->right->left = newNode(6);
    root->right->right = newNode(7);
    root->right->left->right = newNode(8);
    root->right->right->right = newNode(9);
    cout << "Vertical order traversal is \n";

    // Function call
    printVerticalOrder(root);
    return0;
}

