// C# program for printing vertical order of a given binary
// tree
usingSystem;
usingSystem.Collections.Generic;

publicclassVerticalOrderBtree {

    // Tree node
    publicclassNode {
        publicintdata;
        publicNode left;
        publicNode right;

        // Constructor
        publicNode(intval)
        {
            data = val;
            left = null;
            right = null;
        }
    }
    // Store vertical order
    // in map "m", hd = horizontal
    // distance, vd = vertical distance
    staticvoid
    preOrderTraversal(Node root, longhd, longvd,
                      SortedDictionary<long, List<int> > m)
    {
        if(root == null)
            return;
        // key = horizontal
        // distance (30 bits) + vertical
        // distance (30 bits) map
        // will store key in sorted
        // order. Thus nodes having same
        // horizontal distance
        // will sort according to
        // vertical distance.
        longval = hd << 30 | vd;

        // insert in map
        if(m.ContainsKey(val) == true)
            m[val].Add(root.data);
        else{
            List<int> v = newList<int>();
            v.Add(root.data);
            m.Add(val, v);
        }
        preOrderTraversal(root.left, hd - 1, vd + 1, m);
        preOrderTraversal(root.right, hd + 1, vd + 1, m);
    }

    staticvoidverticalOrder(Node root)
    {
        // map to store all nodes in vertical order.
        // keys will be horizontal + vertical distance.
        SortedDictionary<long, List<int> > mp
            = newSortedDictionary<long, List<int> >();

        preOrderTraversal(root, 0, 1, mp);

        // print map
        intprekey = Int32.MaxValue;
        foreach(KeyValuePair<long, List<int> > entry inmp)
        {
            if(prekey != Int32.MaxValue
                && (entry.Key >> 30) != prekey) {
                Console.WriteLine();
            }
            prekey = (int)entry.Key >> 30;
            foreach(intv inentry.Value)
                Console.Write(v + " ");
        }
    }

    // Driver program to test above functions
    publicstaticvoidMain(String[] args)
    {

        Node root = newNode(1);
        root.left = newNode(2);
        root.right = newNode(3);
        root.left.left = newNode(4);
        root.left.right = newNode(5);
        root.right.left = newNode(6);
        root.right.right = newNode(7);
        root.right.left.right = newNode(8);
        root.right.right.right = newNode(9);
        Console.WriteLine("Vertical Order traversal :- ");
        verticalOrder(root);
    }
}

