  For example it returns 'A' for input 10 
  '1' for 1, etc */
chargetNumeral(intval)
{
  if( val >= 0 && val <= 9)
    return(val + '0');
  if( val >= 10 && val <= 14)  
    return(val + 'A'- 10);
    
  /* If we reach this line caller is giving 
    invalid no. so we assert and fail*/
  assert(0);
}

