// C program to check if n is a multiple of 3
#include <stdio.h>
#include<string.h>

intstaticdp[1001];

/* Function to check if n is a multiple of 3*/
intisMultipleOf3(intn)
{
    intodd_count = 0;
    inteven_count = 0;
    
    // Base Cases
    if(n < 0)
        n = -n;
        
    if(n == 0)
        return1;
        
    if(n == 1)
        return0;
    
    // If a value is already present
    // in dp, return it
    if(dp[n] != -1)
        returndp[n];
    
    while(n) {
        /* If odd bit is set then
        increment odd counter */
        if(n & 1)
            odd_count++;

        /* If even bit is set then
        increment even counter */
        if(n & 2)
            even_count++;
        n = n >> 2;
    }
  
  intabs= (odd_count - even_count);
  if(abs<0)
  {
    abs= -1*abs;
  }

    dp[n] = isMultipleOf3(abs);
    
    // return dp
    returndp[n];
}

/* Program to test function isMultipleOf3 */
intmain()
{
    intnum = 24;
    
    memset(dp, -1, sizeof(dp));
    
    if(isMultipleOf3(num))
        printf("%d is multiple of 3", num);
    else
        printf("%d is not a multiple of 3", num);
    return0;
}

