// for uintptr_t
#include <cstdint>
#include <iostream>

structNode {
    intdata;
    // XOR of next and prev
    Node* both;
};

classXORLinkedList {
private:
    Node* head;
    Node* tail;
    // XOR function for Node pointers
    Node* XOR(Node* a, Node* b);

public:
    // Constructor to initialize an empty
    // list
    XORLinkedList();
  
    // Insert a node at the head of the list
    voidinsert_at_head(intdata);
  
    // Insert a node at the tail of the list
    voidinsert_at_tail(intdata);
  
    // Delete a node from the head
    // of the list
    voiddelete_from_head();
  
    // Delete a node from the tail
    // of the list
    voiddelete_from_tail();
  
    // Print the elements of the list
    voidprint_list();
};

XORLinkedList::XORLinkedList()
{
    head = tail = nullptr; // Initialize head and tail to
                           // nullptr for an empty list
}

Node* XORLinkedList::XOR(Node* a, Node* b)
{
    return(
      
        // XOR operation for Node pointers
        Node*)((uintptr_t)(a) ^ (uintptr_t)(b));
}

voidXORLinkedList::insert_at_head(intdata)
{
    Node* new_node = newNode();
    new_node->data = data;
    new_node->both = XOR(nullptr, head);

    if(head) {
        head->both
            = XOR(new_node, XOR(head->both, nullptr));
    }
    else{
        // If the list was empty, the new
        // node is both the head and the
        // tail
        tail = new_node;
    }
    // Update the head to the new node
    head = new_node;
}

voidXORLinkedList::insert_at_tail(intdata)
{
    Node* new_node = newNode();
    new_node->data = data;
    new_node->both = XOR(tail, nullptr);

    if(tail) {
        tail->both
            = XOR(XOR(tail->both, nullptr), new_node);
    }
    else{
        // If the list was empty, the new
        // node is both the head and the
        // tail
        head = new_node;
    }
    // Update the tail to the new node
    tail = new_node;
}

voidXORLinkedList::delete_from_head()
{
    if(head) {
        Node* next = XOR(head->both, nullptr);
        deletehead;
        head = next;

        if(next) {
            next->both = XOR(next->both, head);
        }
        else{
            // If the list becomes empty,
            // update the tail to nullptr
            tail = nullptr;
        }
    }
}

voidXORLinkedList::delete_from_tail()
{
    if(tail) {
        Node* prev = XOR(tail->both, nullptr);
        deletetail;
        tail = prev;

        if(prev) {
            prev->both = XOR(prev->both, tail);
        }
        else{
            // If the list becomes empty, update the head to
            // nullptr
            head = nullptr;
        }
    }
}

voidXORLinkedList::print_list()
{
    Node* current = head;
    Node* prev = nullptr;
    while(current) {
        std::cout << current->data << " ";
        Node* next = XOR(prev, current->both);
        prev = current;
        current = next;
    }
    std::cout << std::endl;
}

