{
    /* Create following Doubly Linked List
    head-->40<-->30<-->20<-->10 */
    structNode *head = NULL;
    insert(&head, 10);
    insert(&head, 20);
    insert(&head, 30);
    insert(&head, 40);

    // print the created list
    printList (head);

    return(0);
}

